CREATE TABLE unit_transfer_unit_control (
  unit_control_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(tenant_id),
  property_ref text NOT NULL CHECK(property_ref=btrim(property_ref) AND length(property_ref) BETWEEN 1 AND 128),
  unit_ref text NOT NULL CHECK(unit_ref=btrim(unit_ref) AND length(unit_ref) BETWEEN 1 AND 128),
  current_owner_entity_id uuid NOT NULL,current_asset_account_codes text[] NOT NULL CHECK(cardinality(current_asset_account_codes) BETWEEN 1 AND 50),currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),
  lifecycle_stage text NOT NULL CHECK(lifecycle_stage IN('CWIP','FINISHED_INVENTORY')),
  version bigint NOT NULL DEFAULT 0 CHECK(version>=0),last_transfer_pair_id uuid,
  initial_owner_entity_id uuid NOT NULL,initial_source_document_id uuid NOT NULL,initial_source_document_line_id uuid NOT NULL,initial_source_payload_hash text NOT NULL CHECK(initial_source_payload_hash~'^sha256:[0-9a-f]{64}$'),
  created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(tenant_id,property_ref,unit_ref),UNIQUE(tenant_id,unit_control_id),
  FOREIGN KEY(tenant_id,current_owner_entity_id) REFERENCES entity(tenant_id,entity_id),
  FOREIGN KEY(tenant_id,initial_owner_entity_id,initial_source_document_id,initial_source_document_line_id) REFERENCES source_document_line(tenant_id,entity_id,source_document_id,source_document_line_id)
);
ALTER TABLE unit_transfer_unit_control ENABLE ROW LEVEL SECURITY;
CREATE POLICY unit_transfer_unit_control_scope ON unit_transfer_unit_control USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(current_owner_entity_id));
REVOKE ALL ON unit_transfer_unit_control FROM PUBLIC,refs_app;

CREATE TABLE unit_transfer_pair (
  unit_transfer_pair_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  unit_control_id uuid NOT NULL,
  tenant_id uuid NOT NULL REFERENCES tenant(tenant_id),
  source_entity_id uuid NOT NULL,
  target_entity_id uuid NOT NULL,
  source_period_id uuid NOT NULL,
  target_period_id uuid NOT NULL,
  transfer_date date NOT NULL,
  currency char(3) NOT NULL CHECK(currency~'^[A-Z]{3}$'),
  unit_ref text NOT NULL CHECK(unit_ref=btrim(unit_ref) AND length(unit_ref) BETWEEN 1 AND 128),
  source_document_id uuid NOT NULL,
  source_document_line_id uuid NOT NULL,
  source_document_version bigint NOT NULL CHECK(source_document_version>=0),
  source_payload_hash text NOT NULL CHECK(source_payload_hash~'^sha256:[0-9a-f]{64}$'),
  source_line_hash text NOT NULL CHECK(source_line_hash~'^sha256:[0-9a-f]{64}$'),
  attachment_ids uuid[] NOT NULL CHECK(cardinality(attachment_ids)>0),
  attachment_snapshot_hash text NOT NULL CHECK(attachment_snapshot_hash~'^sha256:[0-9a-f]{64}$'),
  target_attachment_ids uuid[] NOT NULL CHECK(cardinality(target_attachment_ids)>0),
  target_attachment_snapshot_hash text NOT NULL CHECK(target_attachment_snapshot_hash~'^sha256:[0-9a-f]{64}$'),
  source_mapping_snapshot_id uuid NOT NULL,
  source_mapping_snapshot_hash text NOT NULL CHECK(source_mapping_snapshot_hash~'^sha256:[0-9a-f]{64}$'),
  target_mapping_snapshot_id uuid NOT NULL,
  target_mapping_snapshot_hash text NOT NULL CHECK(target_mapping_snapshot_hash~'^sha256:[0-9a-f]{64}$'),
  source_carrying_account_codes text[] NOT NULL CHECK(cardinality(source_carrying_account_codes) BETWEEN 1 AND 50),
  source_due_from_account_code text NOT NULL,
  source_gain_loss_account_code text NOT NULL,
  target_inventory_account_code text NOT NULL,
  target_due_to_account_code text NOT NULL,
  source_lifecycle_stage text NOT NULL CHECK(source_lifecycle_stage IN('CWIP','FINISHED_INVENTORY')),
  target_lifecycle_stage text NOT NULL CHECK(target_lifecycle_stage IN('CWIP','FINISHED_INVENTORY')),
  carrying_amount numeric(20,4) NOT NULL CHECK(carrying_amount>0),
  source_cost_ledger_line_ids uuid[] NOT NULL CHECK(cardinality(source_cost_ledger_line_ids)>0),
  source_cost_layers jsonb NOT NULL CHECK(jsonb_typeof(source_cost_layers)='array' AND jsonb_array_length(source_cost_layers)>0),
  source_cost_basis_hash text NOT NULL CHECK(source_cost_basis_hash~'^sha256:[0-9a-f]{64}$'),
  expected_unit_version bigint NOT NULL CHECK(expected_unit_version>=0),
  transfer_price numeric(20,4) NOT NULL CHECK(transfer_price>0),
  source_journal_entry_id uuid NOT NULL,
  target_journal_entry_id uuid NOT NULL,
  source_journal_snapshot_hash text NOT NULL CHECK(source_journal_snapshot_hash~'^sha256:[0-9a-f]{64}$'),
  target_journal_snapshot_hash text NOT NULL CHECK(target_journal_snapshot_hash~'^sha256:[0-9a-f]{64}$'),
  status text NOT NULL DEFAULT 'DRAFT_PAIR' CHECK(status IN('DRAFT_PAIR','PENDING_REVIEW_PAIR','PENDING_APPROVAL_PAIR','APPROVED_PAIR','POSTED_PAIR','CANCELLED_PAIR')),
  revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
  created_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  completed_at timestamptz,
  cancelled_by text,cancelled_at timestamptz,cancel_reason text,
  evidence_hash text NOT NULL CHECK(evidence_hash~'^sha256:[0-9a-f]{64}$'),
  CHECK(source_entity_id<>target_entity_id),
  CHECK((status='POSTED_PAIR' AND completed_at IS NOT NULL AND cancelled_at IS NULL AND cancelled_by IS NULL AND cancel_reason IS NULL) OR (status='CANCELLED_PAIR' AND completed_at IS NULL AND cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL AND length(btrim(cancel_reason)) BETWEEN 8 AND 2000) OR (status NOT IN('POSTED_PAIR','CANCELLED_PAIR') AND completed_at IS NULL AND cancelled_at IS NULL AND cancelled_by IS NULL AND cancel_reason IS NULL)),
  UNIQUE(tenant_id,source_entity_id,source_journal_entry_id),
  UNIQUE(tenant_id,target_entity_id,target_journal_entry_id),
  UNIQUE(tenant_id,unit_transfer_pair_id),
  FOREIGN KEY(tenant_id,source_entity_id) REFERENCES entity(tenant_id,entity_id),
  FOREIGN KEY(tenant_id,target_entity_id) REFERENCES entity(tenant_id,entity_id),
  FOREIGN KEY(tenant_id,source_entity_id,source_period_id,source_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,period_id,journal_entry_id),
  FOREIGN KEY(tenant_id,target_entity_id,target_period_id,target_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,period_id,journal_entry_id),
  FOREIGN KEY(tenant_id,source_entity_id,source_document_id,source_document_line_id) REFERENCES source_document_line(tenant_id,entity_id,source_document_id,source_document_line_id),
  FOREIGN KEY(tenant_id,source_mapping_snapshot_id) REFERENCES mapping_snapshot(tenant_id,mapping_snapshot_id),
  FOREIGN KEY(tenant_id,target_mapping_snapshot_id) REFERENCES mapping_snapshot(tenant_id,mapping_snapshot_id),
  FOREIGN KEY(tenant_id,unit_control_id) REFERENCES unit_transfer_unit_control(tenant_id,unit_control_id)
);
ALTER TABLE unit_transfer_unit_control ADD CONSTRAINT unit_transfer_unit_control_last_transfer_pair_tenant_fk
 FOREIGN KEY(tenant_id,last_transfer_pair_id) REFERENCES unit_transfer_pair(tenant_id,unit_transfer_pair_id);
CREATE INDEX unit_transfer_pair_scope_idx ON unit_transfer_pair(tenant_id,source_entity_id,target_entity_id,transfer_date DESC,unit_transfer_pair_id DESC);
CREATE INDEX unit_transfer_pair_source_register_idx ON unit_transfer_pair(tenant_id,source_entity_id,source_period_id,transfer_date DESC,unit_transfer_pair_id DESC);
CREATE INDEX unit_transfer_pair_target_register_idx ON unit_transfer_pair(tenant_id,target_entity_id,target_period_id,transfer_date DESC,unit_transfer_pair_id DESC);
CREATE UNIQUE INDEX unit_transfer_pair_active_source_line_uq ON unit_transfer_pair(tenant_id,source_entity_id,source_document_line_id) WHERE status<>'CANCELLED_PAIR';
CREATE UNIQUE INDEX unit_transfer_pair_one_open_unit_uq ON unit_transfer_pair(tenant_id,unit_control_id) WHERE status NOT IN('POSTED_PAIR','CANCELLED_PAIR');
ALTER TABLE unit_transfer_pair ENABLE ROW LEVEL SECURITY;
CREATE POLICY unit_transfer_pair_scope ON unit_transfer_pair USING(
  tenant_id=refs_current_tenant() AND refs_entity_allowed(source_entity_id) AND refs_entity_allowed(target_entity_id)
);
REVOKE ALL ON unit_transfer_pair FROM PUBLIC,refs_app;

CREATE TABLE unit_transfer_elimination_basis (
  elimination_basis_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),unit_transfer_pair_id uuid NOT NULL UNIQUE,
  tenant_id uuid NOT NULL,source_entity_id uuid NOT NULL,target_entity_id uuid NOT NULL,currency char(3) NOT NULL,
  carrying_amount numeric(20,4) NOT NULL,transfer_price numeric(20,4) NOT NULL,intercompany_profit numeric(20,4) NOT NULL CHECK(intercompany_profit>=0),
  source_journal_entry_id uuid NOT NULL,target_journal_entry_id uuid NOT NULL,source_cost_layers jsonb NOT NULL CHECK(jsonb_typeof(source_cost_layers)='array' AND jsonb_array_length(source_cost_layers)>0),source_cost_basis_hash text NOT NULL,
  evidence_hash text NOT NULL CHECK(evidence_hash~'^sha256:[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  FOREIGN KEY(tenant_id,unit_transfer_pair_id) REFERENCES unit_transfer_pair(tenant_id,unit_transfer_pair_id),
  FOREIGN KEY(tenant_id,source_entity_id,source_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,journal_entry_id),
  FOREIGN KEY(tenant_id,target_entity_id,target_journal_entry_id) REFERENCES journal_entry(tenant_id,entity_id,journal_entry_id)
);
ALTER TABLE unit_transfer_elimination_basis ENABLE ROW LEVEL SECURITY;
CREATE POLICY unit_transfer_elimination_basis_scope ON unit_transfer_elimination_basis USING(
 tenant_id=refs_current_tenant() AND refs_entity_allowed(source_entity_id) AND refs_entity_allowed(target_entity_id));
REVOKE ALL ON unit_transfer_elimination_basis FROM PUBLIC,refs_app;

-- Private, one-shot authorizations let the paired SECURITY DEFINER commands
-- enter the shared Journal lifecycle without trusting caller-settable GUCs.
CREATE TABLE unit_transfer_internal_gate (
 backend_pid integer NOT NULL,transaction_id bigint NOT NULL,tenant_id uuid NOT NULL,
 unit_transfer_pair_id uuid NOT NULL,resource_kind text NOT NULL CHECK(resource_kind IN('JOURNAL','PAIR','UNIT')),
 resource_id uuid NOT NULL,operation text NOT NULL,
 PRIMARY KEY(backend_pid,transaction_id,tenant_id,unit_transfer_pair_id,resource_kind,resource_id,operation)
);
REVOKE ALL ON unit_transfer_internal_gate FROM PUBLIC,refs_app;

CREATE FUNCTION refs_unit_transfer_journal_snapshot(p_tenant uuid,p_entity uuid,p_journal uuid) RETURNS text
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT refs_jsonb_hash(jsonb_build_object('period_id',j.period_id,'journal_date',j.journal_date,'currency',j.currency,'journal_type',j.journal_type,
   'lines',(SELECT jsonb_agg(jsonb_build_object('line_no',l.line_no,'account_code',l.account_code,'debit_amount',l.debit_amount,'credit_amount',l.credit_amount,'member_ref',l.member_ref,'dimensions',l.dimensions) ORDER BY l.line_no)
            FROM journal_line l WHERE l.tenant_id=j.tenant_id AND l.entity_id=j.entity_id AND l.journal_entry_id=j.journal_entry_id)))
 FROM journal_entry j WHERE j.tenant_id=p_tenant AND j.entity_id=p_entity AND j.journal_entry_id=p_journal
$$;

CREATE FUNCTION refs_unit_transfer_attachment_snapshot(p_tenant uuid,p_entity uuid,p_document uuid) RETURNS text
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT CASE WHEN count(*)=0 OR bool_or(a.finalization_status<>'VERIFIED_CLEAN' OR a.scan_status<>'CLEAN' OR a.verified_at IS NULL OR a.finalized_at IS NULL) THEN NULL ELSE refs_jsonb_hash(jsonb_agg(jsonb_build_object(
   'attachment_id',a.attachment_id,'entity_id',a.entity_id,'storage_ref',a.storage_ref,'storage_version',a.storage_version,'content_hash',a.content_hash,
   'scan_status',a.scan_status,'finalization_status',a.finalization_status,'verified_at',a.verified_at,'finalized_at',a.finalized_at) ORDER BY a.attachment_id)) END
 FROM source_link sl JOIN attachment a ON a.tenant_id=sl.tenant_id AND a.entity_id=sl.entity_id AND a.attachment_id=sl.attachment_id
 WHERE sl.tenant_id=p_tenant AND sl.entity_id=p_entity AND sl.source_document_id=p_document AND sl.link_type='SOURCE_ATTACHMENT'
$$;

CREATE FUNCTION refs_unit_transfer_attachment_ids_snapshot(p_tenant uuid,p_entity uuid,p_ids uuid[]) RETURNS text
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT CASE WHEN cardinality(COALESCE(p_ids,'{}'::uuid[]))=0 OR count(*)<>cardinality(p_ids) OR bool_or(a.finalization_status<>'VERIFIED_CLEAN' OR a.scan_status<>'CLEAN' OR a.verified_at IS NULL OR a.finalized_at IS NULL) THEN NULL ELSE refs_jsonb_hash(jsonb_agg(jsonb_build_object(
   'attachment_id',a.attachment_id,'entity_id',a.entity_id,'storage_ref',a.storage_ref,'storage_version',a.storage_version,'content_hash',a.content_hash,
   'scan_status',a.scan_status,'finalization_status',a.finalization_status,'verified_at',a.verified_at,'finalized_at',a.finalized_at) ORDER BY a.attachment_id)) END
 FROM attachment a WHERE a.tenant_id=p_tenant AND a.entity_id=p_entity AND a.attachment_id=ANY(COALESCE(p_ids,'{}'::uuid[]))
$$;

CREATE FUNCTION refs_unit_transfer_mapping_is_current(p_tenant uuid,p_entity uuid,p_mapping uuid,p_date date) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT EXISTS(
  SELECT 1 FROM mapping_snapshot m WHERE m.tenant_id=p_tenant AND m.entity_id=p_entity AND m.mapping_snapshot_id=p_mapping
   AND m.scope_type='ENTITY' AND m.scope_key=p_entity::text AND m.family='INTERCOMPANY_ACCOUNT_PAIR' AND m.status='APPROVED'
   AND m.input_key_hash=refs_jsonb_hash(m.input_keys)
   AND m.effective_from<=(p_date::timestamp AT TIME ZONE 'UTC') AND(m.effective_to IS NULL OR m.effective_to>(p_date::timestamp AT TIME ZONE 'UTC'))
   AND m.snapshot_hash=refs_jsonb_hash(jsonb_build_object('input_keys',m.input_keys,'output_rules',m.output_rules))
   AND NOT EXISTS(SELECT 1 FROM mapping_snapshot higher WHERE higher.tenant_id=m.tenant_id AND higher.entity_id=m.entity_id AND higher.scope_type=m.scope_type AND higher.scope_key=m.scope_key AND higher.family=m.family AND higher.input_key_hash=m.input_key_hash AND higher.input_key_hash=refs_jsonb_hash(higher.input_keys) AND higher.status='APPROVED' AND higher.priority>m.priority AND higher.effective_from<=(p_date::timestamp AT TIME ZONE 'UTC') AND(higher.effective_to IS NULL OR higher.effective_to>(p_date::timestamp AT TIME ZONE 'UTC')))
   AND 1=(SELECT count(*) FROM mapping_snapshot tied WHERE tied.tenant_id=m.tenant_id AND tied.entity_id=m.entity_id AND tied.scope_type=m.scope_type AND tied.scope_key=m.scope_key AND tied.family=m.family AND tied.input_key_hash=m.input_key_hash AND tied.input_key_hash=refs_jsonb_hash(tied.input_keys) AND tied.status='APPROVED' AND tied.priority=m.priority AND tied.effective_from<=(p_date::timestamp AT TIME ZONE 'UTC') AND(tied.effective_to IS NULL OR tied.effective_to>(p_date::timestamp AT TIME ZONE 'UTC')))
 )
$$;

CREATE FUNCTION refs_unit_transfer_cost_snapshot(p_tenant uuid,p_entity uuid,p_date date,p_property text,p_unit text,p_currency char(3),p_accounts text[],p_excluded_journal uuid) RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 WITH raw AS MATERIALIZED(
  SELECT l.ledger_line_id,l.account_code,(l.debit_amount-l.credit_amount)::numeric(20,4) net,
   jsonb_build_object('ledger_line_id',l.ledger_line_id,'journal_entry_id',l.journal_entry_id,'account_code',l.account_code,'currency',l.currency,'debit_amount',l.debit_amount,'credit_amount',l.credit_amount,'dimensions',l.dimensions,'journal_date',j.journal_date,'posted_at',l.posted_at) evidence
  FROM ledger_line l
  JOIN journal_entry j ON j.tenant_id=l.tenant_id AND j.entity_id=l.entity_id AND j.journal_entry_id=l.journal_entry_id AND j.status='POSTED'
  JOIN accounting_period ap ON ap.tenant_id=j.tenant_id AND ap.entity_id=j.entity_id AND ap.period_id=j.period_id AND ap.ledger_code='PRIMARY'
  WHERE l.tenant_id=p_tenant AND l.entity_id=p_entity AND l.account_code=ANY(COALESCE(p_accounts,'{}'::text[])) AND l.currency=p_currency
   AND l.dimensions->>'unit_ref'=p_unit AND l.dimensions->>'property_ref'=p_property AND j.journal_date<=p_date
   AND(p_excluded_journal IS NULL OR j.journal_entry_id<>p_excluded_journal)
 ),layers AS MATERIALIZED(
  SELECT account_code,sum(net)::numeric(20,4) amount,array_agg(ledger_line_id ORDER BY ledger_line_id) ids,refs_jsonb_hash(jsonb_agg(evidence ORDER BY ledger_line_id)) basis_hash
  FROM raw GROUP BY account_code
 ),totals AS(
  SELECT count(*) line_count,sum(net)::numeric(20,4) amount,array_agg(ledger_line_id ORDER BY ledger_line_id) ids,refs_jsonb_hash(jsonb_agg(evidence ORDER BY ledger_line_id)) basis_hash FROM raw
 ),layer_json AS(
  SELECT count(*) layer_count,bool_or(amount<=0) invalid_layer,coalesce(jsonb_agg(jsonb_build_object('account_code',account_code,'amount',amount::text,'ledger_line_ids',to_jsonb(ids),'basis_hash',basis_hash) ORDER BY account_code),'[]'::jsonb) layers FROM layers
 )
 SELECT CASE WHEN totals.line_count=0 OR totals.amount<=0 OR layer_json.layer_count=0 OR layer_json.invalid_layer THEN NULL ELSE jsonb_build_object('amount',totals.amount::text,'ledger_line_ids',to_jsonb(totals.ids),'basis_hash',totals.basis_hash,'layers',layer_json.layers) END
 FROM totals CROSS JOIN layer_json
$$;

CREATE FUNCTION refs_read_unit_transfer_create_options(p_tenant uuid,p_source_entity uuid,p_source_period uuid,p_target_entity uuid,p_date date,p_target_attachment_ids uuid[]) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE source_period accounting_period;target_period accounting_period;source_map mapping_snapshot;target_map mapping_snapshot;source_map_count integer;target_map_count integer;
 target_ids uuid[];target_hash text;target_candidates jsonb;options jsonb;source_currency char(3);target_currency char(3);
BEGIN
 PERFORM refs_assert_scope(p_tenant,p_source_entity,'REAL_ESTATE.UNIT_TRANSFER.VIEW');PERFORM refs_assert_scope(p_tenant,p_target_entity,'REAL_ESTATE.UNIT_TRANSFER.VIEW');
 PERFORM refs_assert_scope(p_tenant,p_source_entity,'REAL_ESTATE.UNIT_TRANSFER.CREATE');PERFORM refs_assert_scope(p_tenant,p_target_entity,'REAL_ESTATE.UNIT_TRANSFER.CREATE');
 PERFORM refs_assert_scope(p_tenant,p_source_entity,'GL.JE.VIEW');PERFORM refs_assert_scope(p_tenant,p_target_entity,'GL.JE.VIEW');
 PERFORM refs_assert_scope(p_tenant,p_source_entity,'GL.JE.CREATE');PERFORM refs_assert_scope(p_tenant,p_target_entity,'GL.JE.CREATE');
 IF p_source_entity=p_target_entity OR p_date IS NULL OR cardinality(COALESCE(p_target_attachment_ids,'{}'::uuid[]))>25 THEN RAISE EXCEPTION 'Invalid Unit Transfer option scope' USING ERRCODE='22023';END IF;
 SELECT base_currency INTO source_currency FROM entity WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND active;SELECT base_currency INTO target_currency FROM entity WHERE tenant_id=p_tenant AND entity_id=p_target_entity AND active;
 IF source_currency IS NULL OR target_currency IS NULL OR source_currency<>target_currency THEN RAISE EXCEPTION 'Unit Transfer requires two active entities with one base currency' USING ERRCODE='0A000';END IF;
 SELECT * INTO source_period FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND period_id=p_source_period AND ledger_code='PRIMARY' AND status='OPEN' AND p_date BETWEEN starts_on AND ends_on;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer source period is unavailable' USING ERRCODE='P0002';END IF;
 SELECT * INTO target_period FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_target_entity AND ledger_code='PRIMARY' AND status='OPEN' AND starts_on=source_period.starts_on AND ends_on=source_period.ends_on AND p_date BETWEEN starts_on AND ends_on;
 IF NOT FOUND THEN RAISE EXCEPTION 'Aligned target period is unavailable' USING ERRCODE='P0002';END IF;
 SELECT count(*) INTO source_map_count FROM mapping_snapshot m WHERE m.tenant_id=p_tenant AND m.entity_id=p_source_entity AND m.scope_type='ENTITY' AND m.scope_key=p_source_entity::text AND m.family='INTERCOMPANY_ACCOUNT_PAIR' AND m.input_keys->>'counterparty_entity_id'=p_target_entity::text AND m.output_rules ?& ARRAY['unit_transfer_carrying_account_codes','unit_transfer_gain_account_code','unit_transfer_source_lifecycle_stage'] AND jsonb_typeof(m.output_rules->'unit_transfer_carrying_account_codes')='array' AND refs_unit_transfer_mapping_is_current(p_tenant,p_source_entity,m.mapping_snapshot_id,p_date);
 SELECT count(*) INTO target_map_count FROM mapping_snapshot m WHERE m.tenant_id=p_tenant AND m.entity_id=p_target_entity AND m.scope_type='ENTITY' AND m.scope_key=p_target_entity::text AND m.family='INTERCOMPANY_ACCOUNT_PAIR' AND m.input_keys->>'counterparty_entity_id'=p_source_entity::text AND m.output_rules ?& ARRAY['unit_transfer_inventory_account_code','unit_transfer_target_lifecycle_stage'] AND refs_unit_transfer_mapping_is_current(p_tenant,p_target_entity,m.mapping_snapshot_id,p_date);
 IF source_map_count<>1 OR target_map_count<>1 THEN RAISE EXCEPTION 'Unit Transfer requires one current reciprocal mapping in each company' USING ERRCODE='55000';END IF;
 SELECT * INTO source_map FROM mapping_snapshot m WHERE m.tenant_id=p_tenant AND m.entity_id=p_source_entity AND m.scope_type='ENTITY' AND m.scope_key=p_source_entity::text AND m.family='INTERCOMPANY_ACCOUNT_PAIR' AND m.input_keys->>'counterparty_entity_id'=p_target_entity::text AND m.output_rules ?& ARRAY['unit_transfer_carrying_account_codes','unit_transfer_gain_account_code','unit_transfer_source_lifecycle_stage'] AND jsonb_typeof(m.output_rules->'unit_transfer_carrying_account_codes')='array' AND refs_unit_transfer_mapping_is_current(p_tenant,p_source_entity,m.mapping_snapshot_id,p_date);
 SELECT * INTO target_map FROM mapping_snapshot m WHERE m.tenant_id=p_tenant AND m.entity_id=p_target_entity AND m.scope_type='ENTITY' AND m.scope_key=p_target_entity::text AND m.family='INTERCOMPANY_ACCOUNT_PAIR' AND m.input_keys->>'counterparty_entity_id'=p_source_entity::text AND m.output_rules ?& ARRAY['unit_transfer_inventory_account_code','unit_transfer_target_lifecycle_stage'] AND refs_unit_transfer_mapping_is_current(p_tenant,p_target_entity,m.mapping_snapshot_id,p_date);
 IF source_map.output_rules->>'counterparty_account_code' IS DISTINCT FROM target_map.input_keys->>'account_code' OR target_map.output_rules->>'counterparty_account_code' IS DISTINCT FROM source_map.input_keys->>'account_code' OR source_map.output_rules->>'unit_transfer_source_lifecycle_stage' NOT IN('CWIP','FINISHED_INVENTORY') OR target_map.output_rules->>'unit_transfer_target_lifecycle_stage' NOT IN('CWIP','FINISHED_INVENTORY') THEN RAISE EXCEPTION 'Unit Transfer reciprocal mappings disagree' USING ERRCODE='55000';END IF;
 SELECT ARRAY(SELECT DISTINCT value FROM unnest(COALESCE(p_target_attachment_ids,'{}'::uuid[])) value ORDER BY value) INTO target_ids;
 IF cardinality(target_ids)<>cardinality(COALESCE(p_target_attachment_ids,'{}'::uuid[])) THEN RAISE EXCEPTION 'Duplicate target attachment identifiers are not allowed' USING ERRCODE='22023';END IF;
 target_hash:=refs_unit_transfer_attachment_ids_snapshot(p_tenant,p_target_entity,target_ids);
 IF cardinality(target_ids)>25 THEN RAISE EXCEPTION 'Select at most 25 target attachments' USING ERRCODE='22023';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('attachment_id',a.attachment_id,'name',a.name,'media_type',a.media_type,'size_bytes',a.size_bytes::text,'content_hash',a.content_hash,'uploaded_at',a.uploaded_at) ORDER BY a.uploaded_at DESC,a.attachment_id DESC),'[]'::jsonb) INTO target_candidates FROM(SELECT * FROM attachment WHERE tenant_id=p_tenant AND entity_id=p_target_entity AND finalization_status='VERIFIED_CLEAN' AND scan_status='CLEAN' AND verified_at IS NOT NULL AND finalized_at IS NOT NULL ORDER BY uploaded_at DESC,attachment_id DESC LIMIT 50)a;
 SELECT coalesce(jsonb_agg(x.option ORDER BY x.document_no,x.unit_ref,x.source_document_line_id),'[]'::jsonb) INTO options FROM(
  SELECT d.document_no,l.unit_ref,l.source_document_line_id,jsonb_build_object('source_document_id',d.source_document_id,'source_document_line_id',l.source_document_line_id,'document_no',NULLIF(btrim(d.document_no),''),'property_ref',l.property_ref,'unit_ref',l.unit_ref,'currency',d.currency,'transfer_price',l.amount::text,'expected_source_version',d.version,'expected_source_hash',d.payload_hash,'expected_source_line_hash',refs_jsonb_hash(to_jsonb(l)),'source_attachment_ids',to_jsonb(a.ids),'expected_source_attachment_hash',refs_unit_transfer_attachment_snapshot(p_tenant,p_source_entity,d.source_document_id),'source_mapping_snapshot_id',source_map.mapping_snapshot_id,'expected_source_mapping_hash',source_map.snapshot_hash,'target_mapping_snapshot_id',target_map.mapping_snapshot_id,'expected_target_mapping_hash',target_map.snapshot_hash,'source_carrying_account_codes',to_jsonb(ARRAY(SELECT value FROM jsonb_array_elements_text(source_map.output_rules->'unit_transfer_carrying_account_codes') value ORDER BY value)),'source_gain_loss_account_code',source_map.output_rules->>'unit_transfer_gain_account_code','target_inventory_account_code',target_map.output_rules->>'unit_transfer_inventory_account_code','source_lifecycle_stage',source_map.output_rules->>'unit_transfer_source_lifecycle_stage','target_lifecycle_stage',target_map.output_rules->>'unit_transfer_target_lifecycle_stage','expected_carrying_amount',c.snapshot->>'amount','source_cost_ledger_line_ids',c.snapshot->'ledger_line_ids','source_cost_layers',c.snapshot->'layers','source_cost_basis_hash',c.snapshot->>'basis_hash','expected_unit_version',coalesce(u.version,0),'target_period_id',target_period.period_id) option
  FROM source_document d JOIN source_document_line l ON l.tenant_id=d.tenant_id AND l.entity_id=d.entity_id AND l.source_document_id=d.source_document_id
  CROSS JOIN LATERAL(SELECT array_agg(DISTINCT sl.attachment_id ORDER BY sl.attachment_id) ids FROM source_link sl WHERE sl.tenant_id=d.tenant_id AND sl.entity_id=d.entity_id AND sl.source_document_id=d.source_document_id AND sl.link_type='SOURCE_ATTACHMENT')a
  CROSS JOIN LATERAL(SELECT refs_unit_transfer_cost_snapshot(p_tenant,p_source_entity,p_date,l.property_ref,l.unit_ref,d.currency,ARRAY(SELECT value FROM jsonb_array_elements_text(source_map.output_rules->'unit_transfer_carrying_account_codes') value ORDER BY value),NULL) snapshot)c
  LEFT JOIN unit_transfer_unit_control u ON u.tenant_id=d.tenant_id AND u.property_ref=l.property_ref AND u.unit_ref=l.unit_ref
  WHERE d.tenant_id=p_tenant AND d.entity_id=p_source_entity AND d.document_type='UNIT_TRANSFER_AUTHORIZATION' AND d.status IN('APPROVED','POSTED') AND d.currency=source_currency AND d.accounting_date BETWEEN source_period.starts_on AND LEAST(source_period.ends_on,p_date) AND d.business_date<=p_date AND l.direction IN('DEBIT','NONE') AND l.amount>0 AND NULLIF(btrim(l.property_ref),'') IS NOT NULL AND NULLIF(btrim(l.unit_ref),'') IS NOT NULL AND refs_unit_transfer_attachment_snapshot(p_tenant,p_source_entity,d.source_document_id) IS NOT NULL AND c.snapshot IS NOT NULL AND (u.unit_control_id IS NULL OR u.current_owner_entity_id=p_source_entity AND u.currency=d.currency AND(u.current_asset_account_codes=ARRAY(SELECT value FROM jsonb_array_elements_text(source_map.output_rules->'unit_transfer_carrying_account_codes') value ORDER BY value) AND u.lifecycle_stage=source_map.output_rules->>'unit_transfer_source_lifecycle_stage' OR u.last_transfer_pair_id IS NULL AND EXISTS(SELECT 1 FROM unit_transfer_pair cancelled WHERE cancelled.tenant_id=u.tenant_id AND cancelled.unit_control_id=u.unit_control_id AND cancelled.status='CANCELLED_PAIR') AND NOT EXISTS(SELECT 1 FROM unit_transfer_pair established WHERE established.tenant_id=u.tenant_id AND established.unit_control_id=u.unit_control_id AND established.status<>'CANCELLED_PAIR'))) AND NOT EXISTS(SELECT 1 FROM unit_transfer_pair p WHERE p.tenant_id=d.tenant_id AND p.status<>'CANCELLED_PAIR' AND(p.source_document_line_id=l.source_document_line_id OR p.unit_control_id=u.unit_control_id AND p.status<>'POSTED_PAIR'))
  ORDER BY d.document_no,l.unit_ref,l.source_document_line_id LIMIT 100)x;
 RETURN jsonb_build_object('schema_version','UNIT_TRANSFER_CREATE_OPTIONS_V1','tenant_id',p_tenant,'source_entity_id',p_source_entity,'target_entity_id',p_target_entity,'source_period_id',p_source_period,'target_period_id',target_period.period_id,'transfer_date',p_date,'currency',source_currency,'options',options,'target_attachment_candidates',target_candidates,'selected_target_attachment_ids',to_jsonb(target_ids),'selected_target_attachment_snapshot_hash',target_hash,'action_flags',jsonb_build_object('can_create_draft',jsonb_array_length(options)>0 AND target_hash IS NOT NULL,'can_submit',false,'can_review',false,'can_approve',false,'can_reject',false,'can_cancel',false,'can_post',false));
END;$$;

CREATE FUNCTION refs_create_unit_transfer_hash(
 p_tenant uuid,p_source_entity uuid,p_target_entity uuid,p_source_period uuid,p_target_period uuid,p_date date,p_unit text,
 p_source_document uuid,p_source_line uuid,p_expected_source_version bigint,p_expected_source_hash text,p_expected_source_line_hash text,p_expected_source_attachment_hash text,p_expected_transfer_price numeric,p_source_mapping uuid,p_expected_source_mapping_hash text,
 p_target_mapping uuid,p_expected_target_mapping_hash text,p_source_carrying_accounts text[],p_source_gain_loss_account text,p_target_inventory_account text,
 p_expected_carrying numeric,p_expected_unit_version bigint,p_target_attachments uuid[],p_expected_target_attachment_hash text,p_source_number text,p_target_number text,p_reason text
) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_COMMAND_V1','tenant_id',p_tenant,'source_entity_id',p_source_entity,
  'target_entity_id',p_target_entity,'source_period_id',p_source_period,'target_period_id',p_target_period,'transfer_date',p_date,'unit_ref',btrim(p_unit),
  'source_document_id',p_source_document,'source_document_line_id',p_source_line,'expected_source_version',p_expected_source_version,
  'expected_source_hash',p_expected_source_hash,'expected_source_line_hash',p_expected_source_line_hash,'expected_source_attachment_hash',p_expected_source_attachment_hash,'expected_transfer_price',p_expected_transfer_price,'source_mapping_snapshot_id',p_source_mapping,'expected_source_mapping_hash',p_expected_source_mapping_hash,
  'target_mapping_snapshot_id',p_target_mapping,'expected_target_mapping_hash',p_expected_target_mapping_hash,'source_carrying_account_codes',to_jsonb(p_source_carrying_accounts),
  'source_gain_loss_account_code',btrim(p_source_gain_loss_account),'target_inventory_account_code',btrim(p_target_inventory_account),
  'expected_carrying_amount',p_expected_carrying,'expected_unit_version',p_expected_unit_version,'target_attachment_ids',to_jsonb(ARRAY(SELECT value FROM unnest(COALESCE(p_target_attachments,'{}'::uuid[])) value ORDER BY value)),'expected_target_attachment_hash',p_expected_target_attachment_hash,'source_journal_number',btrim(p_source_number),'target_journal_number',btrim(p_target_number),'reason',btrim(p_reason)))
$$;

CREATE FUNCTION refs_create_unit_transfer(
 p_tenant uuid,p_source_entity uuid,p_target_entity uuid,p_source_period uuid,p_target_period uuid,p_date date,p_unit text,
 p_source_document uuid,p_source_line uuid,p_expected_source_version bigint,p_expected_source_hash text,p_expected_source_line_hash text,p_expected_source_attachment_hash text,p_expected_transfer_price numeric,p_source_mapping uuid,p_expected_source_mapping_hash text,
 p_target_mapping uuid,p_expected_target_mapping_hash text,p_source_carrying_accounts text[],p_source_gain_loss_account text,p_target_inventory_account text,
 p_expected_carrying numeric,p_expected_unit_version bigint,p_target_attachments uuid[],p_expected_target_attachment_hash text,p_source_number text,p_target_number text,p_reason text,p_idempotency_key text,p_request_hash text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();idem idempotency_receipt;source_period accounting_period;target_period accounting_period;source_document source_document;source_line source_document_line;
 source_map mapping_snapshot;target_map mapping_snapshot;source_entity_row entity;target_entity_row entity;source_due text;target_due text;source_affiliate text;target_affiliate text;currency char(3);carrying numeric(20,4);price numeric(20,4);margin numeric(20,4);
 attachments uuid[];target_attachments uuid[];attachment_hash text;target_attachment_hash text;cost_line_ids uuid[];cost_basis_hash text;cost_snapshot jsonb;cost_layers jsonb;layer_lines jsonb;dims jsonb;source_lines jsonb;target_lines jsonb;source_result jsonb;target_result jsonb;source_journal uuid;target_journal uuid;
 source_snapshot text;target_snapshot text;pair_id uuid:=gen_random_uuid();unit_control unit_transfer_unit_control;evidence text;payload jsonb;inner_hash text;
BEGIN
 PERFORM refs_assert_scope(p_tenant,p_source_entity,'REAL_ESTATE.UNIT_TRANSFER.CREATE');PERFORM refs_assert_scope(p_tenant,p_target_entity,'REAL_ESTATE.UNIT_TRANSFER.CREATE');
 PERFORM refs_assert_scope(p_tenant,p_source_entity,'GL.JE.CREATE');PERFORM refs_assert_scope(p_tenant,p_target_entity,'GL.JE.CREATE');
 PERFORM refs_assert_scope(p_tenant,p_source_entity,'GL.JE.VIEW');PERFORM refs_assert_scope(p_tenant,p_target_entity,'GL.JE.VIEW');
 IF actor IS NULL OR p_source_entity IS NULL OR p_target_entity IS NULL OR p_source_entity=p_target_entity OR p_date IS NULL OR p_expected_source_version IS NULL OR p_expected_source_version<0
  OR p_expected_source_hash IS NULL OR p_expected_source_hash!~'^sha256:[0-9a-f]{64}$' OR p_expected_source_line_hash IS NULL OR p_expected_source_line_hash!~'^sha256:[0-9a-f]{64}$' OR p_expected_source_attachment_hash IS NULL OR p_expected_source_attachment_hash!~'^sha256:[0-9a-f]{64}$'
  OR p_expected_transfer_price IS NULL OR p_expected_transfer_price<=0 OR p_expected_transfer_price>=10000000000000000 OR p_expected_transfer_price<>round(p_expected_transfer_price,4) OR p_expected_source_mapping_hash IS NULL OR p_expected_source_mapping_hash!~'^sha256:[0-9a-f]{64}$'
  OR p_expected_target_mapping_hash IS NULL OR p_expected_target_mapping_hash!~'^sha256:[0-9a-f]{64}$' OR p_expected_carrying IS NULL OR p_expected_carrying<=0 OR p_expected_carrying>=10000000000000000 OR p_expected_carrying<>round(p_expected_carrying,4)
  OR p_expected_unit_version IS NULL OR p_expected_unit_version<0 OR p_expected_target_attachment_hash IS NULL OR p_expected_target_attachment_hash!~'^sha256:[0-9a-f]{64}$' OR cardinality(COALESCE(p_target_attachments,'{}'::uuid[]))=0
  OR cardinality(COALESCE(p_source_carrying_accounts,'{}'::text[])) NOT BETWEEN 1 AND 50 OR p_source_carrying_accounts IS DISTINCT FROM ARRAY(SELECT DISTINCT btrim(value) FROM unnest(COALESCE(p_source_carrying_accounts,'{}'::text[])) value WHERE length(btrim(value)) BETWEEN 1 AND 64 ORDER BY btrim(value))
  OR p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 8 AND 200 OR p_request_hash IS NULL OR p_request_hash!~'^sha256:[0-9a-f]{64}$'
  OR length(btrim(coalesce(p_unit,''))) NOT BETWEEN 1 AND 128 OR length(btrim(coalesce(p_source_number,''))) NOT BETWEEN 1 AND 100
  OR length(btrim(coalesce(p_target_number,''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000
  OR p_request_hash IS DISTINCT FROM refs_create_unit_transfer_hash(p_tenant,p_source_entity,p_target_entity,p_source_period,p_target_period,p_date,p_unit,
    p_source_document,p_source_line,p_expected_source_version,p_expected_source_hash,p_expected_source_line_hash,p_expected_source_attachment_hash,p_expected_transfer_price,p_source_mapping,p_expected_source_mapping_hash,p_target_mapping,
    p_expected_target_mapping_hash,p_source_carrying_accounts,p_source_gain_loss_account,p_target_inventory_account,p_expected_carrying,p_expected_unit_version,p_target_attachments,p_expected_target_attachment_hash,p_source_number,p_target_number,p_reason)
 THEN RAISE EXCEPTION 'Invalid Unit Transfer command' USING ERRCODE='22023';END IF;
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'UNIT_TRANSFER:'||p_source_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='UNIT_TRANSFER:'||p_source_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Unit Transfer idempotency conflict' USING ERRCODE='23505';END IF;
 IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO source_entity_row FROM entity WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND active FOR SHARE;SELECT * INTO target_entity_row FROM entity WHERE tenant_id=p_tenant AND entity_id=p_target_entity AND active FOR SHARE;
 IF source_entity_row.entity_id IS NULL OR target_entity_row.entity_id IS NULL OR source_entity_row.base_currency IS DISTINCT FROM target_entity_row.base_currency THEN RAISE EXCEPTION 'Unit Transfer requires two active entities with one base currency' USING ERRCODE='0A000';END IF;
 SELECT * INTO source_period FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND period_id=p_source_period AND ledger_code='PRIMARY' AND status='OPEN' AND p_date BETWEEN starts_on AND ends_on FOR SHARE;
 SELECT * INTO target_period FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_target_entity AND period_id=p_target_period AND ledger_code='PRIMARY' AND status='OPEN' AND p_date BETWEEN starts_on AND ends_on FOR SHARE;
 IF source_period.period_id IS NULL OR target_period.period_id IS NULL OR source_period.starts_on<>target_period.starts_on OR source_period.ends_on<>target_period.ends_on THEN RAISE EXCEPTION 'Unit Transfer requires aligned OPEN primary periods' USING ERRCODE='55000';END IF;
 SELECT * INTO source_document FROM source_document WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND source_document_id=p_source_document FOR SHARE;
 SELECT * INTO source_line FROM source_document_line WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND source_document_id=p_source_document AND source_document_line_id=p_source_line FOR SHARE;
 IF source_document.source_document_id IS NULL OR source_line.source_document_line_id IS NULL OR source_document.version IS DISTINCT FROM p_expected_source_version OR source_document.payload_hash IS DISTINCT FROM p_expected_source_hash
   OR source_document.status NOT IN('APPROVED','POSTED') OR source_document.document_type<>'UNIT_TRANSFER_AUTHORIZATION' OR source_document.business_date>p_date OR source_document.accounting_date>p_date OR source_document.accounting_date NOT BETWEEN source_period.starts_on AND source_period.ends_on
  OR refs_jsonb_hash(to_jsonb(source_line)) IS DISTINCT FROM p_expected_source_line_hash OR source_line.amount IS DISTINCT FROM p_expected_transfer_price
  OR source_line.unit_ref IS DISTINCT FROM btrim(p_unit) OR NULLIF(btrim(source_line.property_ref),'') IS NULL
 THEN RAISE EXCEPTION 'Unit Transfer source evidence changed' USING ERRCODE='40001';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant::text||':'||source_line.property_ref||':'||btrim(p_unit),0));
 IF EXISTS(SELECT 1 FROM unit_transfer_pair p JOIN unit_transfer_unit_control u ON u.tenant_id=p.tenant_id AND u.unit_control_id=p.unit_control_id WHERE p.tenant_id=p_tenant AND u.property_ref=source_line.property_ref AND u.unit_ref=btrim(p_unit) AND p.status NOT IN('POSTED_PAIR','CANCELLED_PAIR')) THEN RAISE EXCEPTION 'Unit already has an incomplete transfer' USING ERRCODE='23505';END IF;
 currency:=source_document.currency;price:=source_line.amount;IF currency IS DISTINCT FROM source_entity_row.base_currency OR price<=0 OR price>=10000000000000000 OR price<>round(price,4) OR source_line.direction NOT IN('DEBIT','NONE') THEN RAISE EXCEPTION 'Unit Transfer source line must retain a valid same-base-currency unit amount' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT attachment_id ORDER BY attachment_id) INTO attachments FROM source_link WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND source_document_id=p_source_document AND link_type='SOURCE_ATTACHMENT';
 attachment_hash:=refs_unit_transfer_attachment_snapshot(p_tenant,p_source_entity,p_source_document);IF attachment_hash IS NULL OR attachment_hash IS DISTINCT FROM p_expected_source_attachment_hash THEN RAISE EXCEPTION 'Unit Transfer requires the exact verified-clean source attachment snapshot' USING ERRCODE='23514';END IF;
 SELECT ARRAY(SELECT DISTINCT value FROM unnest(p_target_attachments) value ORDER BY value) INTO target_attachments;
 IF cardinality(target_attachments)<>cardinality(p_target_attachments) THEN RAISE EXCEPTION 'Duplicate target attachment identifiers are not allowed' USING ERRCODE='22023';END IF;
 target_attachment_hash:=refs_unit_transfer_attachment_ids_snapshot(p_tenant,p_target_entity,target_attachments);IF target_attachment_hash IS NULL OR target_attachment_hash IS DISTINCT FROM p_expected_target_attachment_hash THEN RAISE EXCEPTION 'Unit Transfer requires exact verified-clean target evidence attachments' USING ERRCODE='23514';END IF;
 SELECT * INTO source_map FROM mapping_snapshot WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND scope_type='ENTITY' AND scope_key=p_source_entity::text AND mapping_snapshot_id=p_source_mapping AND family='INTERCOMPANY_ACCOUNT_PAIR' AND status='APPROVED' AND input_key_hash=refs_jsonb_hash(input_keys) AND snapshot_hash=p_expected_source_mapping_hash AND effective_from<=(p_date::timestamp AT TIME ZONE 'UTC') AND(effective_to IS NULL OR effective_to>(p_date::timestamp AT TIME ZONE 'UTC')) FOR SHARE;
 SELECT * INTO target_map FROM mapping_snapshot WHERE tenant_id=p_tenant AND entity_id=p_target_entity AND scope_type='ENTITY' AND scope_key=p_target_entity::text AND mapping_snapshot_id=p_target_mapping AND family='INTERCOMPANY_ACCOUNT_PAIR' AND status='APPROVED' AND input_key_hash=refs_jsonb_hash(input_keys) AND snapshot_hash=p_expected_target_mapping_hash AND effective_from<=(p_date::timestamp AT TIME ZONE 'UTC') AND(effective_to IS NULL OR effective_to>(p_date::timestamp AT TIME ZONE 'UTC')) FOR SHARE;
 source_due:=source_map.input_keys->>'account_code';target_due:=target_map.input_keys->>'account_code';
 IF source_map.mapping_snapshot_id IS NULL OR target_map.mapping_snapshot_id IS NULL OR source_map.snapshot_hash IS DISTINCT FROM refs_jsonb_hash(jsonb_build_object('input_keys',source_map.input_keys,'output_rules',source_map.output_rules)) OR target_map.snapshot_hash IS DISTINCT FROM refs_jsonb_hash(jsonb_build_object('input_keys',target_map.input_keys,'output_rules',target_map.output_rules))
   OR source_map.input_keys->>'counterparty_entity_id' IS DISTINCT FROM p_target_entity::text OR target_map.input_keys->>'counterparty_entity_id' IS DISTINCT FROM p_source_entity::text OR source_due IS NULL OR target_due IS NULL
   OR source_map.output_rules->>'classification' IS DISTINCT FROM 'DUE_FROM' OR source_map.output_rules->>'counterparty_classification' IS DISTINCT FROM 'DUE_TO' OR source_map.output_rules->>'counterparty_account_code' IS DISTINCT FROM target_due
   OR target_map.output_rules->>'classification' IS DISTINCT FROM 'DUE_TO' OR target_map.output_rules->>'counterparty_classification' IS DISTINCT FROM 'DUE_FROM' OR target_map.output_rules->>'counterparty_account_code' IS DISTINCT FROM source_due
   OR ARRAY(SELECT value FROM jsonb_array_elements_text(source_map.output_rules->'unit_transfer_carrying_account_codes') value ORDER BY value) IS DISTINCT FROM p_source_carrying_accounts
   OR source_map.output_rules->>'unit_transfer_gain_account_code' IS DISTINCT FROM btrim(p_source_gain_loss_account)
   OR target_map.output_rules->>'unit_transfer_inventory_account_code' IS DISTINCT FROM btrim(p_target_inventory_account)
   OR source_map.output_rules->>'unit_transfer_source_lifecycle_stage' NOT IN('CWIP','FINISHED_INVENTORY')
   OR target_map.output_rules->>'unit_transfer_target_lifecycle_stage' NOT IN('CWIP','FINISHED_INVENTORY')
   OR NOT refs_unit_transfer_mapping_is_current(p_tenant,p_source_entity,p_source_mapping,p_date)
   OR NOT refs_unit_transfer_mapping_is_current(p_tenant,p_target_entity,p_target_mapping,p_date)
 THEN RAISE EXCEPTION 'Unit Transfer requires exact reciprocal approved intercompany mappings' USING ERRCODE='23514';END IF;
 IF btrim(p_source_gain_loss_account)=ANY(p_source_carrying_accounts) OR source_due=ANY(p_source_carrying_accounts) OR source_due=btrim(p_source_gain_loss_account) THEN RAISE EXCEPTION 'Unit Transfer source accounts must be distinct by purpose' USING ERRCODE='23514';END IF;
 PERFORM 1 FROM account_master WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND account_code=ANY(p_source_carrying_accounts||ARRAY[btrim(p_source_gain_loss_account),source_due]) AND active GROUP BY tenant_id HAVING count(*)=cardinality(p_source_carrying_accounts)+2;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer source accounts are unavailable' USING ERRCODE='23503';END IF;
 PERFORM 1 FROM account_master WHERE tenant_id=p_tenant AND entity_id=p_target_entity AND account_code IN(btrim(p_target_inventory_account),target_due) AND active GROUP BY tenant_id HAVING count(*)=2;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer target accounts are unavailable' USING ERRCODE='23503';END IF;
 SELECT member_ref INTO source_affiliate FROM member_master WHERE tenant_id=p_tenant AND entity_id=p_source_entity AND member_ref=target_entity_row.entity_code AND member_type='AFFILIATE' AND active FOR SHARE;
 SELECT member_ref INTO target_affiliate FROM member_master WHERE tenant_id=p_tenant AND entity_id=p_target_entity AND member_ref=source_entity_row.entity_code AND member_type='AFFILIATE' AND active FOR SHARE;
 IF source_affiliate IS NULL OR target_affiliate IS NULL THEN RAISE EXCEPTION 'Unit Transfer requires reciprocal active affiliate members' USING ERRCODE='23503';END IF;
 cost_snapshot:=refs_unit_transfer_cost_snapshot(p_tenant,p_source_entity,p_date,source_line.property_ref,btrim(p_unit),currency,p_source_carrying_accounts,NULL);
 IF cost_snapshot IS NULL THEN RAISE EXCEPTION 'Unit Transfer cost layers are incomplete or invalid' USING ERRCODE='23514';END IF;
 carrying:=(cost_snapshot->>'amount')::numeric;cost_line_ids:=ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(cost_snapshot->'ledger_line_ids') value ORDER BY value::uuid);cost_basis_hash:=cost_snapshot->>'basis_hash';cost_layers:=cost_snapshot->'layers';
 IF carrying<=0 OR carrying<>p_expected_carrying THEN RAISE EXCEPTION 'Unit Transfer carrying amount changed' USING ERRCODE='40001';END IF;
 SELECT * INTO unit_control FROM unit_transfer_unit_control WHERE tenant_id=p_tenant AND property_ref=source_line.property_ref AND unit_ref=btrim(p_unit) FOR UPDATE;
 IF NOT FOUND THEN
  IF p_expected_unit_version<>0 OR EXISTS(SELECT 1 FROM ledger_line l JOIN journal_entry j ON j.tenant_id=l.tenant_id AND j.entity_id=l.entity_id AND j.journal_entry_id=l.journal_entry_id AND j.status='POSTED' JOIN accounting_period ap ON ap.tenant_id=j.tenant_id AND ap.entity_id=j.entity_id AND ap.period_id=j.period_id AND ap.ledger_code='PRIMARY' WHERE l.tenant_id=p_tenant AND l.entity_id<>p_source_entity AND l.currency=currency AND l.dimensions->>'unit_ref'=btrim(p_unit) AND l.dimensions->>'property_ref'=source_line.property_ref GROUP BY l.entity_id HAVING sum(l.debit_amount-l.credit_amount)>0) THEN RAISE EXCEPTION 'Unit ownership evidence is ambiguous or stale' USING ERRCODE='40001';END IF;
  INSERT INTO unit_transfer_unit_control(tenant_id,property_ref,unit_ref,current_owner_entity_id,current_asset_account_codes,currency,lifecycle_stage,initial_owner_entity_id,initial_source_document_id,initial_source_document_line_id,initial_source_payload_hash,created_by) VALUES(p_tenant,source_line.property_ref,btrim(p_unit),p_source_entity,p_source_carrying_accounts,currency,source_map.output_rules->>'unit_transfer_source_lifecycle_stage',p_source_entity,p_source_document,p_source_line,source_document.payload_hash,actor) RETURNING * INTO unit_control;
 ELSE
  IF unit_control.version<>p_expected_unit_version OR unit_control.current_owner_entity_id<>p_source_entity OR unit_control.currency<>currency THEN RAISE EXCEPTION 'Unit ownership or version changed' USING ERRCODE='40001';END IF;
  IF unit_control.current_asset_account_codes<>p_source_carrying_accounts OR unit_control.lifecycle_stage<>source_map.output_rules->>'unit_transfer_source_lifecycle_stage' THEN
   IF unit_control.last_transfer_pair_id IS NOT NULL OR EXISTS(SELECT 1 FROM unit_transfer_pair prior WHERE prior.tenant_id=p_tenant AND prior.unit_control_id=unit_control.unit_control_id AND prior.status<>'CANCELLED_PAIR') THEN RAISE EXCEPTION 'Established Unit ownership profile cannot be rebaselined' USING ERRCODE='40001';END IF;
   INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,pair_id,'UNIT',unit_control.unit_control_id,'REBASELINED');
   payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_UNIT_REBASELINE_V1','unit_transfer_pair_id',pair_id,'unit_control_id',unit_control.unit_control_id,'source_entity_id',p_source_entity,'target_entity_id',p_target_entity,'before_version',unit_control.version,'after_version',unit_control.version+1,'before_account_codes',to_jsonb(unit_control.current_asset_account_codes),'after_account_codes',to_jsonb(p_source_carrying_accounts),'before_lifecycle_stage',unit_control.lifecycle_stage,'after_lifecycle_stage',source_map.output_rules->>'unit_transfer_source_lifecycle_stage');
   UPDATE unit_transfer_unit_control SET current_asset_account_codes=p_source_carrying_accounts,lifecycle_stage=source_map.output_rules->>'unit_transfer_source_lifecycle_stage',version=version+1,updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND unit_control_id=unit_control.unit_control_id AND version=p_expected_unit_version RETURNING * INTO unit_control;IF NOT FOUND THEN RAISE EXCEPTION 'Unit ownership rebaseline revision conflict' USING ERRCODE='40001';END IF;
   INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_source_entity,'UNIT_TRANSFER_UNIT_REBASELINED','UNIT_TRANSFER_UNIT_CONTROL',unit_control.unit_control_id,'REBASELINE',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.CREATE',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
   INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_target_entity,'UNIT_TRANSFER_UNIT_REBASELINED','UNIT_TRANSFER_UNIT_CONTROL',unit_control.unit_control_id,'REBASELINE',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.CREATE',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
   INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_source_entity,'UNIT_TRANSFER_UNIT_CONTROL',unit_control.unit_control_id,'UNIT_TRANSFER_UNIT_REBASELINED',payload,refs_jsonb_hash(payload));
   INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_target_entity,'UNIT_TRANSFER_UNIT_CONTROL',unit_control.unit_control_id,'UNIT_TRANSFER_UNIT_REBASELINED',payload,refs_jsonb_hash(payload));
  END IF;
 END IF;
 margin:=price-carrying;IF margin<0 THEN RAISE EXCEPTION 'Transfer below carrying amount requires a separately approved impairment workflow' USING ERRCODE='0A000';END IF;dims:=jsonb_build_object('unit_control_id',unit_control.unit_control_id,'unit_ref',btrim(p_unit),'property_ref',source_line.property_ref,'unit_transfer_pair_id',pair_id,'counterparty_entity_id',p_target_entity);
 SELECT jsonb_agg(jsonb_build_object('line_no',layer.ordinality+1,'account_code',layer.value->>'account_code','debit_amount',0,'credit_amount',(layer.value->>'amount')::numeric,'member_ref',NULL,'dimensions',dims) ORDER BY layer.ordinality) INTO layer_lines FROM jsonb_array_elements(cost_layers) WITH ORDINALITY layer(value,ordinality);
 source_lines:=jsonb_build_array(jsonb_build_object('line_no',1,'account_code',source_due,'debit_amount',price,'credit_amount',0,'member_ref',source_affiliate,'dimensions',dims))||layer_lines;
 IF margin>0 THEN source_lines:=source_lines||jsonb_build_array(jsonb_build_object('line_no',jsonb_array_length(source_lines)+1,'account_code',btrim(p_source_gain_loss_account),'debit_amount',0,'credit_amount',margin,'member_ref',NULL,'dimensions',dims));END IF;
 dims:=jsonb_build_object('unit_control_id',unit_control.unit_control_id,'unit_ref',btrim(p_unit),'property_ref',source_line.property_ref,'unit_transfer_pair_id',pair_id,'counterparty_entity_id',p_source_entity);
 target_lines:=jsonb_build_array(jsonb_build_object('line_no',1,'account_code',btrim(p_target_inventory_account),'debit_amount',price,'credit_amount',0,'member_ref',NULL,'dimensions',dims),jsonb_build_object('line_no',2,'account_code',target_due,'debit_amount',0,'credit_amount',price,'member_ref',target_affiliate,'dimensions',dims));
 inner_hash:=refs_create_manual_journal_hash(p_tenant,p_source_entity,p_source_period,p_source_number,p_date,currency,btrim(p_reason),source_lines,attachments);source_result:=refs_create_manual_journal(p_tenant,p_source_entity,p_source_period,p_source_number,p_date,currency,btrim(p_reason),source_lines,attachments,'unit-transfer-source:'||pair_id,inner_hash);source_journal:=(source_result->>'journal_entry_id')::uuid;
 inner_hash:=refs_create_manual_journal_hash(p_tenant,p_target_entity,p_target_period,p_target_number,p_date,currency,btrim(p_reason),target_lines,target_attachments);target_result:=refs_create_manual_journal(p_tenant,p_target_entity,p_target_period,p_target_number,p_date,currency,btrim(p_reason),target_lines,target_attachments,'unit-transfer-target:'||pair_id,inner_hash);target_journal:=(target_result->>'journal_entry_id')::uuid;
 INSERT INTO source_link(tenant_id,entity_id,link_type,source_document_id,source_document_line_id,journal_entry_id,created_by) VALUES(p_tenant,p_source_entity,'SOURCE_TO_JE',p_source_document,p_source_line,source_journal,actor);
 source_snapshot:=refs_unit_transfer_journal_snapshot(p_tenant,p_source_entity,source_journal);target_snapshot:=refs_unit_transfer_journal_snapshot(p_tenant,p_target_entity,target_journal);
evidence:=refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_EVIDENCE_V1','unit_transfer_pair_id',pair_id,'unit_control_id',unit_control.unit_control_id,'expected_unit_version',unit_control.version,'source_entity_id',p_source_entity,'target_entity_id',p_target_entity,'source_period_id',p_source_period,'target_period_id',p_target_period,'transfer_date',p_date,'currency',currency,'property_ref',source_line.property_ref,'unit_ref',btrim(p_unit),'source_lifecycle_stage',source_map.output_rules->>'unit_transfer_source_lifecycle_stage','target_lifecycle_stage',target_map.output_rules->>'unit_transfer_target_lifecycle_stage','source_document_id',p_source_document,'source_document_line_id',p_source_line,'source_document_version',source_document.version,'source_payload_hash',source_document.payload_hash,'source_line_hash',refs_jsonb_hash(to_jsonb(source_line)),'attachment_snapshot_hash',attachment_hash,'target_attachment_snapshot_hash',target_attachment_hash,'source_mapping_snapshot_id',source_map.mapping_snapshot_id,'source_mapping_snapshot_hash',source_map.snapshot_hash,'target_mapping_snapshot_id',target_map.mapping_snapshot_id,'target_mapping_snapshot_hash',target_map.snapshot_hash,'source_carrying_account_codes',to_jsonb(p_source_carrying_accounts),'source_cost_ledger_line_ids',to_jsonb(cost_line_ids),'source_cost_layers',cost_layers,'source_cost_basis_hash',cost_basis_hash,'carrying_amount',carrying,'transfer_price',price,'source_journal_entry_id',source_journal,'target_journal_entry_id',target_journal,'source_journal_snapshot_hash',source_snapshot,'target_journal_snapshot_hash',target_snapshot));
 INSERT INTO unit_transfer_pair(unit_transfer_pair_id,unit_control_id,tenant_id,source_entity_id,target_entity_id,source_period_id,target_period_id,transfer_date,currency,unit_ref,source_document_id,source_document_line_id,source_document_version,source_payload_hash,source_line_hash,attachment_ids,attachment_snapshot_hash,target_attachment_ids,target_attachment_snapshot_hash,source_mapping_snapshot_id,source_mapping_snapshot_hash,target_mapping_snapshot_id,target_mapping_snapshot_hash,source_carrying_account_codes,source_due_from_account_code,source_gain_loss_account_code,target_inventory_account_code,target_due_to_account_code,source_lifecycle_stage,target_lifecycle_stage,carrying_amount,source_cost_ledger_line_ids,source_cost_layers,source_cost_basis_hash,expected_unit_version,transfer_price,source_journal_entry_id,target_journal_entry_id,source_journal_snapshot_hash,target_journal_snapshot_hash,created_by,evidence_hash)
 VALUES(pair_id,unit_control.unit_control_id,p_tenant,p_source_entity,p_target_entity,p_source_period,p_target_period,p_date,currency,btrim(p_unit),p_source_document,p_source_line,source_document.version,source_document.payload_hash,refs_jsonb_hash(to_jsonb(source_line)),attachments,attachment_hash,target_attachments,target_attachment_hash,source_map.mapping_snapshot_id,source_map.snapshot_hash,target_map.mapping_snapshot_id,target_map.snapshot_hash,p_source_carrying_accounts,source_due,btrim(p_source_gain_loss_account),btrim(p_target_inventory_account),target_due,source_map.output_rules->>'unit_transfer_source_lifecycle_stage',target_map.output_rules->>'unit_transfer_target_lifecycle_stage',carrying,cost_line_ids,cost_layers,cost_basis_hash,unit_control.version,price,source_journal,target_journal,source_snapshot,target_snapshot,actor,evidence);
 payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_DRAFT_PAIR_V1','unit_transfer_pair_id',pair_id,'source_entity_id',p_source_entity,'target_entity_id',p_target_entity,'unit_ref',btrim(p_unit),'currency',currency,'carrying_amount',carrying::text,'transfer_price',price::text,'source_journal_entry_id',source_journal,'target_journal_entry_id',target_journal,'status','DRAFT_PAIR','revision',0,'evidence_hash',evidence,'idempotent',false);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_source_entity,'UNIT_TRANSFER_DRAFT_PAIR_CREATED','UNIT_TRANSFER_PAIR',pair_id,'CREATE',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.CREATE',p_idempotency_key,p_idempotency_key,p_idempotency_key,evidence,btrim(p_reason),payload);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_target_entity,'UNIT_TRANSFER_DRAFT_PAIR_CREATED','UNIT_TRANSFER_PAIR',pair_id,'CREATE',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.CREATE',p_idempotency_key,p_idempotency_key,p_idempotency_key,evidence,btrim(p_reason),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_source_entity,'UNIT_TRANSFER_PAIR',pair_id,'UNIT_TRANSFER_DRAFT_PAIR_CREATED',payload,refs_jsonb_hash(payload));
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_target_entity,'UNIT_TRANSFER_PAIR',pair_id,'UNIT_TRANSFER_DRAFT_PAIR_CREATED',payload,refs_jsonb_hash(payload));
 UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=201,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

CREATE FUNCTION refs_guard_unit_transfer_journal_transition() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE pair unit_transfer_pair;gate integer;current_carrying numeric(20,4);current_cost_ids uuid[];current_cost_hash text;current_cost_layers jsonb;current_cost_snapshot jsonb;source_period accounting_period;target_period accounting_period;source_map mapping_snapshot;target_map mapping_snapshot;
BEGIN
 IF TG_OP='INSERT' THEN
  IF(NEW.reversal_of_id IS NOT NULL OR NEW.reclass_of_id IS NOT NULL) AND EXISTS(SELECT 1 FROM unit_transfer_pair p WHERE p.tenant_id=NEW.tenant_id AND(p.source_journal_entry_id IN(NEW.reversal_of_id,NEW.reclass_of_id) OR p.target_journal_entry_id IN(NEW.reversal_of_id,NEW.reclass_of_id))) THEN RAISE EXCEPTION 'Unit Transfer journals require a dedicated paired reversal' USING ERRCODE='0A000';END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM unit_transfer_pair p WHERE p.tenant_id=OLD.tenant_id AND(p.source_entity_id=OLD.entity_id AND p.source_journal_entry_id=OLD.journal_entry_id OR p.target_entity_id=OLD.entity_id AND p.target_journal_entry_id=OLD.journal_entry_id)) THEN RAISE EXCEPTION 'Unit Transfer Journals are retained evidence and cannot be deleted' USING ERRCODE='55000';END IF;
  RETURN OLD;
 END IF;
 SELECT * INTO pair FROM unit_transfer_pair WHERE tenant_id=NEW.tenant_id AND(source_journal_entry_id IN(NEW.journal_entry_id,NEW.reversal_of_id,NEW.reclass_of_id) OR target_journal_entry_id IN(NEW.journal_entry_id,NEW.reversal_of_id,NEW.reclass_of_id)) FOR UPDATE;
 IF NOT FOUND THEN RETURN NEW;END IF;
 IF NEW.journal_entry_id NOT IN(pair.source_journal_entry_id,pair.target_journal_entry_id) THEN RAISE EXCEPTION 'Unit Transfer journals cannot use generic reversal or reclass' USING ERRCODE='0A000';END IF;
 IF NEW.status IS NOT DISTINCT FROM OLD.status OR (NEW.journal_entry_id,NEW.tenant_id,NEW.entity_id,NEW.period_id,NEW.journal_number,NEW.journal_type,NEW.journal_date,NEW.currency,NEW.description,NEW.created_by,NEW.reversal_of_id,NEW.reclass_of_id,NEW.created_at) IS DISTINCT FROM (OLD.journal_entry_id,OLD.tenant_id,OLD.entity_id,OLD.period_id,OLD.journal_number,OLD.journal_type,OLD.journal_date,OLD.currency,OLD.description,OLD.created_by,OLD.reversal_of_id,OLD.reclass_of_id,OLD.created_at) THEN RAISE EXCEPTION 'Unit Transfer Journal headers are retained evidence' USING ERRCODE='55000';END IF;
 DELETE FROM unit_transfer_internal_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=NEW.tenant_id AND unit_transfer_pair_id=pair.unit_transfer_pair_id AND resource_kind='JOURNAL' AND resource_id=NEW.journal_entry_id AND operation=NEW.status RETURNING 1 INTO gate;
 IF gate IS NULL THEN RAISE EXCEPTION 'Unit Transfer journals must transition as one authorized pair' USING ERRCODE='0A000';END IF;
 IF NEW.status='POSTED' THEN
  IF pair.source_journal_snapshot_hash<>refs_unit_transfer_journal_snapshot(pair.tenant_id,pair.source_entity_id,pair.source_journal_entry_id) OR pair.target_journal_snapshot_hash<>refs_unit_transfer_journal_snapshot(pair.tenant_id,pair.target_entity_id,pair.target_journal_entry_id) THEN RAISE EXCEPTION 'Unit Transfer financial lines changed; create a corrected pair' USING ERRCODE='23514';END IF;
  IF pair.attachment_snapshot_hash IS DISTINCT FROM refs_unit_transfer_attachment_snapshot(pair.tenant_id,pair.source_entity_id,pair.source_document_id) OR pair.target_attachment_snapshot_hash IS DISTINCT FROM refs_unit_transfer_attachment_ids_snapshot(pair.tenant_id,pair.target_entity_id,pair.target_attachment_ids) OR NOT EXISTS(SELECT 1 FROM source_document d JOIN source_document_line l ON l.tenant_id=d.tenant_id AND l.entity_id=d.entity_id AND l.source_document_id=d.source_document_id WHERE d.tenant_id=pair.tenant_id AND d.entity_id=pair.source_entity_id AND d.source_document_id=pair.source_document_id AND d.version=pair.source_document_version AND d.payload_hash=pair.source_payload_hash AND d.status IN('APPROVED','POSTED') AND d.document_type='UNIT_TRANSFER_AUTHORIZATION' AND d.business_date<=pair.transfer_date AND d.accounting_date<=pair.transfer_date AND d.currency=pair.currency AND l.source_document_line_id=pair.source_document_line_id AND l.unit_ref=pair.unit_ref AND l.amount=pair.transfer_price AND refs_jsonb_hash(to_jsonb(l))=pair.source_line_hash) THEN RAISE EXCEPTION 'Unit Transfer source evidence changed before Post' USING ERRCODE='40001';END IF;
  current_cost_snapshot:=refs_unit_transfer_cost_snapshot(pair.tenant_id,pair.source_entity_id,pair.transfer_date,(SELECT property_ref FROM unit_transfer_unit_control WHERE tenant_id=pair.tenant_id AND unit_control_id=pair.unit_control_id),pair.unit_ref,pair.currency,pair.source_carrying_account_codes,pair.source_journal_entry_id);
  current_carrying:=(current_cost_snapshot->>'amount')::numeric;current_cost_ids:=ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(current_cost_snapshot->'ledger_line_ids') value ORDER BY value::uuid);current_cost_hash:=current_cost_snapshot->>'basis_hash';current_cost_layers:=current_cost_snapshot->'layers';
  IF current_cost_snapshot IS NULL OR current_carrying<>pair.carrying_amount OR current_cost_ids IS DISTINCT FROM pair.source_cost_ledger_line_ids OR current_cost_layers IS DISTINCT FROM pair.source_cost_layers OR current_cost_hash IS DISTINCT FROM pair.source_cost_basis_hash THEN RAISE EXCEPTION 'Unit Transfer cost basis changed before Post' USING ERRCODE='40001';END IF;
   SELECT * INTO source_map FROM mapping_snapshot WHERE tenant_id=pair.tenant_id AND entity_id=pair.source_entity_id AND scope_type='ENTITY' AND scope_key=pair.source_entity_id::text AND mapping_snapshot_id=pair.source_mapping_snapshot_id AND family='INTERCOMPANY_ACCOUNT_PAIR' AND status='APPROVED' AND input_key_hash=refs_jsonb_hash(input_keys) AND snapshot_hash=pair.source_mapping_snapshot_hash AND effective_from<=(pair.transfer_date::timestamp AT TIME ZONE 'UTC') AND(effective_to IS NULL OR effective_to>(pair.transfer_date::timestamp AT TIME ZONE 'UTC')) FOR SHARE;
   SELECT * INTO target_map FROM mapping_snapshot WHERE tenant_id=pair.tenant_id AND entity_id=pair.target_entity_id AND scope_type='ENTITY' AND scope_key=pair.target_entity_id::text AND mapping_snapshot_id=pair.target_mapping_snapshot_id AND family='INTERCOMPANY_ACCOUNT_PAIR' AND status='APPROVED' AND input_key_hash=refs_jsonb_hash(input_keys) AND snapshot_hash=pair.target_mapping_snapshot_hash AND effective_from<=(pair.transfer_date::timestamp AT TIME ZONE 'UTC') AND(effective_to IS NULL OR effective_to>(pair.transfer_date::timestamp AT TIME ZONE 'UTC')) FOR SHARE;
  IF source_map.mapping_snapshot_id IS NULL OR target_map.mapping_snapshot_id IS NULL OR NOT refs_unit_transfer_mapping_is_current(pair.tenant_id,pair.source_entity_id,pair.source_mapping_snapshot_id,pair.transfer_date) OR NOT refs_unit_transfer_mapping_is_current(pair.tenant_id,pair.target_entity_id,pair.target_mapping_snapshot_id,pair.transfer_date) OR source_map.snapshot_hash IS DISTINCT FROM refs_jsonb_hash(jsonb_build_object('input_keys',source_map.input_keys,'output_rules',source_map.output_rules)) OR target_map.snapshot_hash IS DISTINCT FROM refs_jsonb_hash(jsonb_build_object('input_keys',target_map.input_keys,'output_rules',target_map.output_rules)) OR source_map.input_keys->>'counterparty_entity_id' IS DISTINCT FROM pair.target_entity_id::text OR target_map.input_keys->>'counterparty_entity_id' IS DISTINCT FROM pair.source_entity_id::text OR source_map.input_keys->>'account_code' IS DISTINCT FROM pair.source_due_from_account_code OR target_map.input_keys->>'account_code' IS DISTINCT FROM pair.target_due_to_account_code OR source_map.output_rules->>'counterparty_account_code' IS DISTINCT FROM pair.target_due_to_account_code OR target_map.output_rules->>'counterparty_account_code' IS DISTINCT FROM pair.source_due_from_account_code OR ARRAY(SELECT value FROM jsonb_array_elements_text(source_map.output_rules->'unit_transfer_carrying_account_codes') value ORDER BY value) IS DISTINCT FROM pair.source_carrying_account_codes OR source_map.output_rules->>'unit_transfer_gain_account_code' IS DISTINCT FROM pair.source_gain_loss_account_code OR target_map.output_rules->>'unit_transfer_inventory_account_code' IS DISTINCT FROM pair.target_inventory_account_code OR source_map.output_rules->>'unit_transfer_source_lifecycle_stage' IS DISTINCT FROM pair.source_lifecycle_stage OR target_map.output_rules->>'unit_transfer_target_lifecycle_stage' IS DISTINCT FROM pair.target_lifecycle_stage THEN RAISE EXCEPTION 'Unit Transfer approved mappings changed before Post' USING ERRCODE='40001';END IF;
  SELECT * INTO source_period FROM accounting_period WHERE tenant_id=pair.tenant_id AND entity_id=pair.source_entity_id AND period_id=pair.source_period_id AND ledger_code='PRIMARY' AND status='OPEN' FOR SHARE;SELECT * INTO target_period FROM accounting_period WHERE tenant_id=pair.tenant_id AND entity_id=pair.target_entity_id AND period_id=pair.target_period_id AND ledger_code='PRIMARY' AND status='OPEN' FOR SHARE;
  IF source_period.period_id IS NULL OR target_period.period_id IS NULL OR source_period.starts_on<>target_period.starts_on OR source_period.ends_on<>target_period.ends_on OR NOT EXISTS(SELECT 1 FROM unit_transfer_unit_control u WHERE u.tenant_id=pair.tenant_id AND u.unit_control_id=pair.unit_control_id AND u.current_owner_entity_id=pair.source_entity_id AND u.version=pair.expected_unit_version FOR SHARE) THEN RAISE EXCEPTION 'Unit Transfer period or ownership changed before Post' USING ERRCODE='40001';END IF;
  IF pair.attachment_ids IS DISTINCT FROM ARRAY(SELECT sl.attachment_id FROM source_link sl WHERE sl.tenant_id=pair.tenant_id AND sl.entity_id=pair.source_entity_id AND sl.journal_entry_id=pair.source_journal_entry_id AND sl.link_type='JE_ATTACHMENT' ORDER BY sl.attachment_id) OR pair.target_attachment_ids IS DISTINCT FROM ARRAY(SELECT sl.attachment_id FROM source_link sl WHERE sl.tenant_id=pair.tenant_id AND sl.entity_id=pair.target_entity_id AND sl.journal_entry_id=pair.target_journal_entry_id AND sl.link_type='JE_ATTACHMENT' ORDER BY sl.attachment_id) THEN RAISE EXCEPTION 'Unit Transfer Journal attachments changed before Post' USING ERRCODE='40001';END IF;
 END IF;
 RETURN NEW;
END;$$;

CREATE FUNCTION refs_protect_unit_transfer_pair() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE gate integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Unit Transfer evidence is immutable' USING ERRCODE='55000';END IF;
 DELETE FROM unit_transfer_internal_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=NEW.tenant_id AND unit_transfer_pair_id=NEW.unit_transfer_pair_id AND resource_kind='PAIR' AND resource_id=NEW.unit_transfer_pair_id AND operation=NEW.status RETURNING 1 INTO gate;
 IF gate IS NULL OR (NEW.unit_control_id,NEW.tenant_id,NEW.source_entity_id,NEW.target_entity_id,NEW.source_period_id,NEW.target_period_id,NEW.transfer_date,NEW.currency,NEW.unit_ref,NEW.source_document_id,NEW.source_document_line_id,NEW.source_document_version,NEW.source_payload_hash,NEW.source_line_hash,NEW.attachment_ids,NEW.attachment_snapshot_hash,NEW.target_attachment_ids,NEW.target_attachment_snapshot_hash,NEW.source_mapping_snapshot_id,NEW.source_mapping_snapshot_hash,NEW.target_mapping_snapshot_id,NEW.target_mapping_snapshot_hash,NEW.source_carrying_account_codes,NEW.source_due_from_account_code,NEW.source_gain_loss_account_code,NEW.target_inventory_account_code,NEW.target_due_to_account_code,NEW.source_lifecycle_stage,NEW.target_lifecycle_stage,NEW.carrying_amount,NEW.source_cost_ledger_line_ids,NEW.source_cost_layers,NEW.source_cost_basis_hash,NEW.expected_unit_version,NEW.transfer_price,NEW.source_journal_entry_id,NEW.target_journal_entry_id,NEW.source_journal_snapshot_hash,NEW.target_journal_snapshot_hash,NEW.created_by,NEW.created_at,NEW.evidence_hash) IS DISTINCT FROM (OLD.unit_control_id,OLD.tenant_id,OLD.source_entity_id,OLD.target_entity_id,OLD.source_period_id,OLD.target_period_id,OLD.transfer_date,OLD.currency,OLD.unit_ref,OLD.source_document_id,OLD.source_document_line_id,OLD.source_document_version,OLD.source_payload_hash,OLD.source_line_hash,OLD.attachment_ids,OLD.attachment_snapshot_hash,OLD.target_attachment_ids,OLD.target_attachment_snapshot_hash,OLD.source_mapping_snapshot_id,OLD.source_mapping_snapshot_hash,OLD.target_mapping_snapshot_id,OLD.target_mapping_snapshot_hash,OLD.source_carrying_account_codes,OLD.source_due_from_account_code,OLD.source_gain_loss_account_code,OLD.target_inventory_account_code,OLD.target_due_to_account_code,OLD.source_lifecycle_stage,OLD.target_lifecycle_stage,OLD.carrying_amount,OLD.source_cost_ledger_line_ids,OLD.source_cost_layers,OLD.source_cost_basis_hash,OLD.expected_unit_version,OLD.transfer_price,OLD.source_journal_entry_id,OLD.target_journal_entry_id,OLD.source_journal_snapshot_hash,OLD.target_journal_snapshot_hash,OLD.created_by,OLD.created_at,OLD.evidence_hash) OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Unit Transfer evidence is immutable' USING ERRCODE='55000';END IF;
 IF NOT(OLD.status='DRAFT_PAIR' AND NEW.status IN('PENDING_REVIEW_PAIR','CANCELLED_PAIR') OR OLD.status='PENDING_REVIEW_PAIR' AND NEW.status IN('PENDING_APPROVAL_PAIR','DRAFT_PAIR') OR OLD.status='PENDING_APPROVAL_PAIR' AND NEW.status IN('APPROVED_PAIR','DRAFT_PAIR') OR OLD.status='APPROVED_PAIR' AND NEW.status='POSTED_PAIR') THEN RAISE EXCEPTION 'Unit Transfer lifecycle transition is invalid' USING ERRCODE='55000';END IF;
 IF NEW.status='CANCELLED_PAIR' THEN
  IF OLD.status<>'DRAFT_PAIR' OR OLD.cancelled_by IS NOT NULL OR OLD.cancelled_at IS NOT NULL OR OLD.cancel_reason IS NOT NULL OR NEW.completed_at IS NOT NULL OR NEW.cancelled_by IS NULL OR NEW.cancelled_at IS NULL OR length(btrim(coalesce(NEW.cancel_reason,''))) NOT BETWEEN 8 AND 2000 THEN RAISE EXCEPTION 'Unit Transfer cancellation transition is invalid' USING ERRCODE='55000';END IF;
 ELSIF NEW.status='POSTED_PAIR' THEN
  IF OLD.status<>'APPROVED_PAIR' OR NEW.completed_at IS NULL OR (NEW.cancelled_by,NEW.cancelled_at,NEW.cancel_reason) IS DISTINCT FROM (OLD.cancelled_by,OLD.cancelled_at,OLD.cancel_reason) THEN RAISE EXCEPTION 'Unit Transfer Post transition is invalid' USING ERRCODE='55000';END IF;
 ELSE
  IF NEW.completed_at IS DISTINCT FROM OLD.completed_at OR (NEW.cancelled_by,NEW.cancelled_at,NEW.cancel_reason) IS DISTINCT FROM (OLD.cancelled_by,OLD.cancelled_at,OLD.cancel_reason) THEN RAISE EXCEPTION 'Unit Transfer lifecycle metadata is immutable' USING ERRCODE='55000';END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER unit_transfer_pair_protect BEFORE UPDATE OR DELETE ON unit_transfer_pair FOR EACH ROW EXECUTE FUNCTION refs_protect_unit_transfer_pair();
CREATE FUNCTION refs_protect_unit_transfer_unit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE gate integer;op_name text:=CASE WHEN NEW.last_transfer_pair_id IS DISTINCT FROM OLD.last_transfer_pair_id THEN 'TRANSFERRED' ELSE 'REBASELINED' END;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Unit ownership evidence is immutable outside controlled Unit Transfer commands' USING ERRCODE='55000';END IF;
 DELETE FROM unit_transfer_internal_gate g WHERE g.backend_pid=pg_backend_pid() AND g.transaction_id=txid_current() AND g.tenant_id=NEW.tenant_id AND g.resource_kind='UNIT' AND g.resource_id=NEW.unit_control_id AND g.operation=op_name AND(op_name='REBASELINED' OR g.unit_transfer_pair_id=NEW.last_transfer_pair_id) RETURNING 1 INTO gate;
 IF gate IS NULL OR (NEW.tenant_id,NEW.property_ref,NEW.unit_ref,NEW.currency,NEW.initial_owner_entity_id,NEW.initial_source_document_id,NEW.initial_source_document_line_id,NEW.initial_source_payload_hash,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.tenant_id,OLD.property_ref,OLD.unit_ref,OLD.currency,OLD.initial_owner_entity_id,OLD.initial_source_document_id,OLD.initial_source_document_line_id,OLD.initial_source_payload_hash,OLD.created_by,OLD.created_at) OR NEW.version<>OLD.version+1 OR op_name='REBASELINED' AND(NEW.current_owner_entity_id<>OLD.current_owner_entity_id OR NEW.last_transfer_pair_id IS DISTINCT FROM OLD.last_transfer_pair_id) THEN RAISE EXCEPTION 'Unit ownership evidence is immutable outside controlled Unit Transfer commands' USING ERRCODE='55000';END IF;RETURN NEW;END;$$;
CREATE TRIGGER unit_transfer_unit_protect BEFORE UPDATE OR DELETE ON unit_transfer_unit_control FOR EACH ROW EXECUTE FUNCTION refs_protect_unit_transfer_unit();
CREATE TRIGGER unit_transfer_journal_transition_guard BEFORE UPDATE OR DELETE ON journal_entry FOR EACH ROW EXECUTE FUNCTION refs_guard_unit_transfer_journal_transition();
CREATE TRIGGER unit_transfer_journal_insert_guard BEFORE INSERT ON journal_entry FOR EACH ROW EXECUTE FUNCTION refs_guard_unit_transfer_journal_transition();
CREATE FUNCTION refs_guard_unit_transfer_journal_line_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE row_tenant uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.tenant_id ELSE NEW.tenant_id END;row_entity uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.entity_id ELSE NEW.entity_id END;row_journal uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.journal_entry_id ELSE NEW.journal_entry_id END;
BEGIN
 IF EXISTS(SELECT 1 FROM unit_transfer_pair p WHERE p.tenant_id=row_tenant AND(p.source_entity_id=row_entity AND p.source_journal_entry_id=row_journal OR p.target_entity_id=row_entity AND p.target_journal_entry_id=row_journal)) THEN RAISE EXCEPTION 'Unit Transfer Journal lines are retained evidence and cannot be edited' USING ERRCODE='55000';END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;$$;
CREATE TRIGGER unit_transfer_journal_line_guard BEFORE INSERT OR UPDATE OR DELETE ON journal_line FOR EACH ROW EXECUTE FUNCTION refs_guard_unit_transfer_journal_line_mutation();
CREATE FUNCTION refs_guard_unit_transfer_source_link_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE row_tenant uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.tenant_id ELSE NEW.tenant_id END;row_entity uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.entity_id ELSE NEW.entity_id END;row_journal uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.journal_entry_id ELSE NEW.journal_entry_id END;
BEGIN
 IF row_journal IS NOT NULL AND EXISTS(SELECT 1 FROM unit_transfer_pair p WHERE p.tenant_id=row_tenant AND(p.source_entity_id=row_entity AND p.source_journal_entry_id=row_journal OR p.target_entity_id=row_entity AND p.target_journal_entry_id=row_journal)) THEN RAISE EXCEPTION 'Unit Transfer Journal lineage is retained evidence and cannot be edited' USING ERRCODE='55000';END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;$$;
CREATE TRIGGER unit_transfer_source_link_guard BEFORE INSERT OR UPDATE OR DELETE ON source_link FOR EACH ROW EXECUTE FUNCTION refs_guard_unit_transfer_source_link_mutation();

CREATE FUNCTION refs_unit_transfer_transition_hash(p_tenant uuid,p_entity uuid,p_pair uuid,p_action text,p_expected_pair_revision bigint,p_expected_source_revision bigint,p_expected_target_revision bigint,p_reason text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_TRANSITION_V1','tenant_id',p_tenant,'entity_id',p_entity,'unit_transfer_pair_id',p_pair,'action',upper(p_action),'expected_pair_revision',p_expected_pair_revision,'expected_source_revision',p_expected_source_revision,'expected_target_revision',p_expected_target_revision,'reason',NULLIF(btrim(p_reason),'')))
$$;
CREATE FUNCTION refs_transition_unit_transfer_pair(p_tenant uuid,p_entity uuid,p_pair uuid,p_action text,p_expected_pair_revision bigint,p_expected_source_revision bigint,p_expected_target_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();pair unit_transfer_pair;idem idempotency_receipt;action text:=upper(p_action);target_status text;source_hash text;target_hash text;source_result jsonb;target_result jsonb;payload jsonb;
BEGIN
 IF actor IS NULL OR action NOT IN('SUBMIT','REVIEW','APPROVE','REJECT') OR p_expected_pair_revision IS NULL OR p_expected_pair_revision<0 OR p_expected_source_revision IS NULL OR p_expected_source_revision<0 OR p_expected_target_revision IS NULL OR p_expected_target_revision<0 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR p_request_hash IS NULL OR p_request_hash!~'^sha256:[0-9a-f]{64}$' OR p_request_hash IS DISTINCT FROM refs_unit_transfer_transition_hash(p_tenant,p_entity,p_pair,action,p_expected_pair_revision,p_expected_source_revision,p_expected_target_revision,p_reason) THEN RAISE EXCEPTION 'Invalid Unit Transfer transition' USING ERRCODE='22023';END IF;
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'UNIT_TRANSFER_'||action||':'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='UNIT_TRANSFER_'||action||':'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Unit Transfer transition idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO pair FROM unit_transfer_pair WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair AND p_entity IN(source_entity_id,target_entity_id) FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer pair not found' USING ERRCODE='P0002';END IF;
 IF pair.revision<>p_expected_pair_revision THEN RAISE EXCEPTION 'Unit Transfer pair revision conflict' USING ERRCODE='40001';END IF;
 PERFORM refs_assert_scope(p_tenant,pair.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.'||action);PERFORM refs_assert_scope(p_tenant,pair.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.'||action);
 target_status:=CASE action WHEN 'SUBMIT' THEN 'PENDING_REVIEW_PAIR' WHEN 'REVIEW' THEN 'PENDING_APPROVAL_PAIR' WHEN 'APPROVE' THEN 'APPROVED_PAIR' ELSE 'DRAFT_PAIR' END;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'JOURNAL',pair.source_journal_entry_id,replace(target_status,'_PAIR',''));
 source_hash:=refs_journal_transition_hash(p_tenant,pair.source_entity_id,pair.source_journal_entry_id,action,p_expected_source_revision,p_reason);source_result:=refs_transition_journal(p_tenant,pair.source_entity_id,pair.source_journal_entry_id,action,p_expected_source_revision,p_reason,'unit-transfer:'||p_pair||':source:'||action||':'||p_idempotency_key,source_hash);
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'JOURNAL',pair.target_journal_entry_id,replace(target_status,'_PAIR',''));
 target_hash:=refs_journal_transition_hash(p_tenant,pair.target_entity_id,pair.target_journal_entry_id,action,p_expected_target_revision,p_reason);target_result:=refs_transition_journal(p_tenant,pair.target_entity_id,pair.target_journal_entry_id,action,p_expected_target_revision,p_reason,'unit-transfer:'||p_pair||':target:'||action||':'||p_idempotency_key,target_hash);
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'PAIR',p_pair,target_status);
 UPDATE unit_transfer_pair SET status=target_status,revision=revision+1 WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair;
 payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_TRANSITION_RECEIPT_V1','unit_transfer_pair_id',p_pair,'status',target_status,'revision',pair.revision+1,'source_journal',source_result,'target_journal',target_result,'idempotent',false);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,pair.source_entity_id,'UNIT_TRANSFER_'||action,'UNIT_TRANSFER_PAIR',p_pair,action,actor,'USER','REAL_ESTATE.UNIT_TRANSFER.'||action,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),NULLIF(btrim(p_reason),''),payload);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,pair.target_entity_id,'UNIT_TRANSFER_'||action,'UNIT_TRANSFER_PAIR',p_pair,action,actor,'USER','REAL_ESTATE.UNIT_TRANSFER.'||action,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),NULLIF(btrim(p_reason),''),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,pair.source_entity_id,'UNIT_TRANSFER_PAIR',p_pair,'UNIT_TRANSFER_'||action,payload,refs_jsonb_hash(payload));
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,pair.target_entity_id,'UNIT_TRANSFER_PAIR',p_pair,'UNIT_TRANSFER_'||action,payload,refs_jsonb_hash(payload));
 UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

CREATE FUNCTION refs_unit_transfer_cancel_hash(p_tenant uuid,p_entity uuid,p_pair uuid,p_expected_pair_revision bigint,p_expected_source_revision bigint,p_expected_target_revision bigint,p_reason text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_CANCEL_COMMAND_V1','tenant_id',p_tenant,'entity_id',p_entity,'unit_transfer_pair_id',p_pair,'expected_pair_revision',p_expected_pair_revision,'expected_source_revision',p_expected_source_revision,'expected_target_revision',p_expected_target_revision,'reason',NULLIF(btrim(p_reason),'')))
$$;
CREATE FUNCTION refs_cancel_unit_transfer_pair(p_tenant uuid,p_entity uuid,p_pair uuid,p_expected_pair_revision bigint,p_expected_source_revision bigint,p_expected_target_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();pair unit_transfer_pair;idem idempotency_receipt;source_journal journal_entry;target_journal journal_entry;payload jsonb;cancelled_at timestamptz;
BEGIN
 IF actor IS NULL OR p_expected_pair_revision IS NULL OR p_expected_pair_revision<0 OR p_expected_source_revision IS NULL OR p_expected_source_revision<0 OR p_expected_target_revision IS NULL OR p_expected_target_revision<0 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR p_request_hash IS NULL OR p_request_hash!~'^sha256:[0-9a-f]{64}$' OR p_request_hash IS DISTINCT FROM refs_unit_transfer_cancel_hash(p_tenant,p_entity,p_pair,p_expected_pair_revision,p_expected_source_revision,p_expected_target_revision,p_reason) THEN RAISE EXCEPTION 'Invalid Unit Transfer cancellation' USING ERRCODE='22023';END IF;
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'UNIT_TRANSFER_CANCEL:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='UNIT_TRANSFER_CANCEL:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Unit Transfer cancellation idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO pair FROM unit_transfer_pair WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair AND p_entity IN(source_entity_id,target_entity_id) FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer pair not found' USING ERRCODE='P0002';END IF;
 IF pair.status<>'DRAFT_PAIR' OR pair.revision<>p_expected_pair_revision THEN RAISE EXCEPTION 'Only the expected Draft Unit Transfer pair can be cancelled' USING ERRCODE='40001';END IF;
 PERFORM refs_assert_scope(p_tenant,pair.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.CANCEL');PERFORM refs_assert_scope(p_tenant,pair.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.CANCEL');
 PERFORM 1 FROM journal_entry j WHERE j.tenant_id=p_tenant AND(j.entity_id=pair.source_entity_id AND j.journal_entry_id=pair.source_journal_entry_id OR j.entity_id=pair.target_entity_id AND j.journal_entry_id=pair.target_journal_entry_id) ORDER BY j.entity_id,j.journal_entry_id FOR UPDATE;
 SELECT * INTO source_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=pair.source_entity_id AND journal_entry_id=pair.source_journal_entry_id;
 SELECT * INTO target_journal FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=pair.target_entity_id AND journal_entry_id=pair.target_journal_entry_id;
 IF source_journal.journal_entry_id IS NULL OR target_journal.journal_entry_id IS NULL OR source_journal.status<>'DRAFT' OR target_journal.status<>'DRAFT' OR source_journal.revision<>p_expected_source_revision OR target_journal.revision<>p_expected_target_revision OR EXISTS(SELECT 1 FROM ledger_line l WHERE l.tenant_id=p_tenant AND(l.entity_id=pair.source_entity_id AND l.journal_entry_id=pair.source_journal_entry_id OR l.entity_id=pair.target_entity_id AND l.journal_entry_id=pair.target_journal_entry_id)) OR pair.source_journal_snapshot_hash IS DISTINCT FROM refs_unit_transfer_journal_snapshot(p_tenant,pair.source_entity_id,pair.source_journal_entry_id) OR pair.target_journal_snapshot_hash IS DISTINCT FROM refs_unit_transfer_journal_snapshot(p_tenant,pair.target_entity_id,pair.target_journal_entry_id) OR pair.attachment_ids IS DISTINCT FROM ARRAY(SELECT sl.attachment_id FROM source_link sl WHERE sl.tenant_id=p_tenant AND sl.entity_id=pair.source_entity_id AND sl.journal_entry_id=pair.source_journal_entry_id AND sl.link_type='JE_ATTACHMENT' ORDER BY sl.attachment_id) OR pair.target_attachment_ids IS DISTINCT FROM ARRAY(SELECT sl.attachment_id FROM source_link sl WHERE sl.tenant_id=p_tenant AND sl.entity_id=pair.target_entity_id AND sl.journal_entry_id=pair.target_journal_entry_id AND sl.link_type='JE_ATTACHMENT' ORDER BY sl.attachment_id) THEN RAISE EXCEPTION 'Unit Transfer Draft Journals changed before cancellation' USING ERRCODE='40001';END IF;
 IF actor=pair.created_by OR actor=source_journal.created_by OR actor=target_journal.created_by THEN RAISE EXCEPTION 'Unit Transfer creator cannot cancel the pair' USING ERRCODE='42501';END IF;
 cancelled_at:=clock_timestamp();
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'PAIR',p_pair,'CANCELLED_PAIR');
 UPDATE unit_transfer_pair SET status='CANCELLED_PAIR',revision=revision+1,cancelled_by=actor,cancelled_at=cancelled_at,cancel_reason=btrim(p_reason) WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair;
 payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_CANCEL_RECEIPT_V1','unit_transfer_pair_id',p_pair,'status','CANCELLED_PAIR','revision',pair.revision+1,'source_journal_entry_id',pair.source_journal_entry_id,'source_journal_revision',source_journal.revision,'target_journal_entry_id',pair.target_journal_entry_id,'target_journal_revision',target_journal.revision,'cancelled_by',actor,'cancelled_at',cancelled_at,'cancel_reason',btrim(p_reason),'pair_evidence_hash',pair.evidence_hash,'idempotent',false);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,pair.source_entity_id,'UNIT_TRANSFER_CANCELLED','UNIT_TRANSFER_PAIR',p_pair,'CANCEL',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.CANCEL',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,pair.target_entity_id,'UNIT_TRANSFER_CANCELLED','UNIT_TRANSFER_PAIR',p_pair,'CANCEL',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.CANCEL',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,pair.source_entity_id,'UNIT_TRANSFER_PAIR',p_pair,'UNIT_TRANSFER_CANCELLED',payload,refs_jsonb_hash(payload));
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,pair.target_entity_id,'UNIT_TRANSFER_PAIR',p_pair,'UNIT_TRANSFER_CANCELLED',payload,refs_jsonb_hash(payload));
 UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

CREATE FUNCTION refs_unit_transfer_post_hash(p_tenant uuid,p_entity uuid,p_pair uuid,p_expected_pair_revision bigint,p_expected_source_revision bigint,p_expected_target_revision bigint) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_POST_V1','tenant_id',p_tenant,'entity_id',p_entity,'unit_transfer_pair_id',p_pair,'expected_pair_revision',p_expected_pair_revision,'expected_source_revision',p_expected_source_revision,'expected_target_revision',p_expected_target_revision))
$$;
CREATE FUNCTION refs_post_unit_transfer_pair(p_tenant uuid,p_entity uuid,p_pair uuid,p_expected_pair_revision bigint,p_expected_source_revision bigint,p_expected_target_revision bigint,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();pair unit_transfer_pair;idem idempotency_receipt;source_hash text;target_hash text;source_result jsonb;target_result jsonb;payload jsonb;
BEGIN
 IF actor IS NULL OR p_expected_pair_revision IS NULL OR p_expected_pair_revision<0 OR p_expected_source_revision IS NULL OR p_expected_source_revision<0 OR p_expected_target_revision IS NULL OR p_expected_target_revision<0 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS NULL OR p_request_hash!~'^sha256:[0-9a-f]{64}$' OR p_request_hash IS DISTINCT FROM refs_unit_transfer_post_hash(p_tenant,p_entity,p_pair,p_expected_pair_revision,p_expected_source_revision,p_expected_target_revision) THEN RAISE EXCEPTION 'Invalid Unit Transfer Post command' USING ERRCODE='22023';END IF;
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'UNIT_TRANSFER_POST:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='UNIT_TRANSFER_POST:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Unit Transfer Post idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO pair FROM unit_transfer_pair WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair AND p_entity IN(source_entity_id,target_entity_id) FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer pair not found' USING ERRCODE='P0002';END IF;
 IF pair.status<>'APPROVED_PAIR' OR pair.revision<>p_expected_pair_revision THEN RAISE EXCEPTION 'Unit Transfer pair is not approved at the expected revision' USING ERRCODE='40001';END IF;
 PERFORM refs_assert_scope(p_tenant,pair.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.POST');PERFORM refs_assert_scope(p_tenant,pair.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.POST');
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'JOURNAL',pair.source_journal_entry_id,'POSTED');
 source_hash:=refs_jsonb_hash(jsonb_build_object('tenantId',p_tenant,'entityId',pair.source_entity_id,'periodId',pair.source_period_id,'journalEntryId',pair.source_journal_entry_id,'expectedRevision',p_expected_source_revision));source_result:=refs_post_journal(p_tenant,pair.source_entity_id,pair.source_period_id,pair.source_journal_entry_id,p_expected_source_revision,'unit-transfer:'||p_pair||':source:POST:'||p_idempotency_key,source_hash,actor);
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'JOURNAL',pair.target_journal_entry_id,'POSTED');
 target_hash:=refs_jsonb_hash(jsonb_build_object('tenantId',p_tenant,'entityId',pair.target_entity_id,'periodId',pair.target_period_id,'journalEntryId',pair.target_journal_entry_id,'expectedRevision',p_expected_target_revision));target_result:=refs_post_journal(p_tenant,pair.target_entity_id,pair.target_period_id,pair.target_journal_entry_id,p_expected_target_revision,'unit-transfer:'||p_pair||':target:POST:'||p_idempotency_key,target_hash,actor);
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'UNIT',pair.unit_control_id,'TRANSFERRED');
 UPDATE unit_transfer_unit_control SET current_owner_entity_id=pair.target_entity_id,current_asset_account_codes=ARRAY[pair.target_inventory_account_code],lifecycle_stage=pair.target_lifecycle_stage,version=version+1,last_transfer_pair_id=p_pair,updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND unit_control_id=pair.unit_control_id AND current_owner_entity_id=pair.source_entity_id AND current_asset_account_codes=pair.source_carrying_account_codes AND lifecycle_stage=pair.source_lifecycle_stage AND version=pair.expected_unit_version;IF NOT FOUND THEN RAISE EXCEPTION 'Unit ownership changed before Post' USING ERRCODE='40001';END IF;
 INSERT INTO unit_transfer_internal_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_pair,'PAIR',p_pair,'POSTED_PAIR');
 UPDATE unit_transfer_pair SET status='POSTED_PAIR',revision=revision+1,completed_at=clock_timestamp() WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair;
 INSERT INTO unit_transfer_elimination_basis(unit_transfer_pair_id,tenant_id,source_entity_id,target_entity_id,currency,carrying_amount,transfer_price,intercompany_profit,source_journal_entry_id,target_journal_entry_id,source_cost_layers,source_cost_basis_hash,evidence_hash) VALUES(p_pair,p_tenant,pair.source_entity_id,pair.target_entity_id,pair.currency,pair.carrying_amount,pair.transfer_price,pair.transfer_price-pair.carrying_amount,pair.source_journal_entry_id,pair.target_journal_entry_id,pair.source_cost_layers,pair.source_cost_basis_hash,refs_jsonb_hash(jsonb_build_object('schema_version','UNIT_TRANSFER_ELIMINATION_BASIS_V1','unit_transfer_pair_id',p_pair,'source_entity_id',pair.source_entity_id,'target_entity_id',pair.target_entity_id,'currency',pair.currency,'carrying_amount',pair.carrying_amount,'transfer_price',pair.transfer_price,'intercompany_profit',pair.transfer_price-pair.carrying_amount,'source_cost_layers',pair.source_cost_layers,'source_cost_basis_hash',pair.source_cost_basis_hash,'source_journal_entry_id',pair.source_journal_entry_id,'target_journal_entry_id',pair.target_journal_entry_id)));
 payload:=jsonb_build_object('schema_version','UNIT_TRANSFER_POST_RECEIPT_V1','unit_transfer_pair_id',p_pair,'unit_control_id',pair.unit_control_id,'unit_version',pair.expected_unit_version+1,'status','POSTED_PAIR','revision',pair.revision+1,'source_journal',source_result,'target_journal',target_result,'idempotent',false);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,metadata) VALUES(p_tenant,pair.source_entity_id,'UNIT_TRANSFER_POSTED','UNIT_TRANSFER_PAIR',p_pair,'POST',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.POST',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),payload);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,metadata) VALUES(p_tenant,pair.target_entity_id,'UNIT_TRANSFER_POSTED','UNIT_TRANSFER_PAIR',p_pair,'POST',actor,'USER','REAL_ESTATE.UNIT_TRANSFER.POST',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,pair.source_entity_id,'UNIT_TRANSFER_PAIR',p_pair,'UNIT_TRANSFER_POSTED',payload,refs_jsonb_hash(payload));
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,pair.target_entity_id,'UNIT_TRANSFER_PAIR',p_pair,'UNIT_TRANSFER_POSTED',payload,refs_jsonb_hash(payload));
 UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

CREATE FUNCTION refs_read_unit_transfer_pair(p_tenant uuid,p_entity uuid,p_pair uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();p unit_transfer_pair;u unit_transfer_unit_control;source_status text;target_status text;source_revision bigint;target_revision bigint;source_created text;source_reviewed text;source_approved text;target_created text;target_reviewed text;target_approved text;elimination jsonb;
BEGIN
 PERFORM refs_assert_scope(p_tenant,p_entity,'REAL_ESTATE.UNIT_TRANSFER.VIEW');PERFORM refs_assert_scope(p_tenant,p_entity,'GL.JE.VIEW');SELECT * INTO p FROM unit_transfer_pair WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p_pair AND p_entity IN(source_entity_id,target_entity_id);
 IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer pair not found' USING ERRCODE='P0002';END IF;PERFORM refs_assert_scope(p_tenant,p.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.VIEW');PERFORM refs_assert_scope(p_tenant,p.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.VIEW');PERFORM refs_assert_scope(p_tenant,p.source_entity_id,'GL.JE.VIEW');PERFORM refs_assert_scope(p_tenant,p.target_entity_id,'GL.JE.VIEW');
 SELECT * INTO u FROM unit_transfer_unit_control WHERE tenant_id=p_tenant AND unit_control_id=p.unit_control_id;
 SELECT status::text,revision,created_by,reviewed_by,approved_by INTO source_status,source_revision,source_created,source_reviewed,source_approved FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=p.source_entity_id AND journal_entry_id=p.source_journal_entry_id;SELECT status::text,revision,created_by,reviewed_by,approved_by INTO target_status,target_revision,target_created,target_reviewed,target_approved FROM journal_entry WHERE tenant_id=p_tenant AND entity_id=p.target_entity_id AND journal_entry_id=p.target_journal_entry_id;
 SELECT jsonb_build_object('elimination_basis_id',elimination_basis_id,'intercompany_profit',intercompany_profit::text,'evidence_hash',evidence_hash) INTO elimination FROM unit_transfer_elimination_basis WHERE tenant_id=p_tenant AND unit_transfer_pair_id=p.unit_transfer_pair_id;
 RETURN jsonb_build_object('schema_version','UNIT_TRANSFER_PAIR_V1','unit_transfer_pair_id',p.unit_transfer_pair_id,'unit_control_id',p.unit_control_id,'property_ref',u.property_ref,'current_owner_entity_id',u.current_owner_entity_id,'current_unit_version',u.version::text,'source_entity_id',p.source_entity_id,'target_entity_id',p.target_entity_id,'source_period_id',p.source_period_id,'target_period_id',p.target_period_id,'transfer_date',p.transfer_date,'currency',p.currency,'unit_ref',p.unit_ref,'carrying_amount',p.carrying_amount::text,'transfer_price',p.transfer_price::text,'source_carrying_account_codes',to_jsonb(p.source_carrying_account_codes),'source_cost_ledger_line_ids',to_jsonb(p.source_cost_ledger_line_ids),'source_cost_layers',p.source_cost_layers,'source_cost_basis_hash',p.source_cost_basis_hash,'source_document_id',p.source_document_id,'source_document_line_id',p.source_document_line_id,'source_document_version',p.source_document_version::text,'source_payload_hash',p.source_payload_hash,'source_line_hash',p.source_line_hash,'source_attachment_ids',to_jsonb(p.attachment_ids),'source_attachment_snapshot_hash',p.attachment_snapshot_hash,'target_attachment_ids',to_jsonb(p.target_attachment_ids),'target_attachment_snapshot_hash',p.target_attachment_snapshot_hash,'source_mapping_snapshot_id',p.source_mapping_snapshot_id,'source_mapping_snapshot_hash',p.source_mapping_snapshot_hash,'target_mapping_snapshot_id',p.target_mapping_snapshot_id,'target_mapping_snapshot_hash',p.target_mapping_snapshot_hash,'source_due_from_account_code',p.source_due_from_account_code,'source_gain_account_code',p.source_gain_loss_account_code,'target_inventory_account_code',p.target_inventory_account_code,'target_due_to_account_code',p.target_due_to_account_code,'source_lifecycle_stage',p.source_lifecycle_stage,'target_lifecycle_stage',p.target_lifecycle_stage,'source_journal_entry_id',p.source_journal_entry_id,'source_journal_status',source_status,'source_journal_revision',source_revision::text,'target_journal_entry_id',p.target_journal_entry_id,'target_journal_status',target_status,'target_journal_revision',target_revision::text,'status',p.status,'revision',p.revision::text,'evidence_hash',p.evidence_hash,'elimination_basis',elimination,'created_by',p.created_by,'created_at',p.created_at,'completed_at',p.completed_at,'cancelled_by',p.cancelled_by,'cancelled_at',p.cancelled_at,'cancel_reason',p.cancel_reason,'action_flags',jsonb_build_object('can_create_draft',false,'can_submit',p.status='DRAFT_PAIR' AND refs_entity_has_permission(p.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.SUBMIT') AND refs_entity_has_permission(p.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.SUBMIT') AND refs_entity_has_permission(p.source_entity_id,'GL.JE.SUBMIT') AND refs_entity_has_permission(p.target_entity_id,'GL.JE.SUBMIT'),'can_review',p.status='PENDING_REVIEW_PAIR' AND refs_entity_has_permission(p.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVIEW') AND refs_entity_has_permission(p.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REVIEW') AND refs_entity_has_permission(p.source_entity_id,'GL.JE.REVIEW') AND refs_entity_has_permission(p.target_entity_id,'GL.JE.REVIEW') AND actor IS DISTINCT FROM source_created AND actor IS DISTINCT FROM target_created,'can_approve',p.status='PENDING_APPROVAL_PAIR' AND refs_entity_has_permission(p.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.APPROVE') AND refs_entity_has_permission(p.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.APPROVE') AND refs_entity_has_permission(p.source_entity_id,'GL.JE.APPROVE') AND refs_entity_has_permission(p.target_entity_id,'GL.JE.APPROVE') AND actor IS DISTINCT FROM source_created AND actor IS DISTINCT FROM source_reviewed AND actor IS DISTINCT FROM target_created AND actor IS DISTINCT FROM target_reviewed,'can_reject',p.status IN('PENDING_REVIEW_PAIR','PENDING_APPROVAL_PAIR') AND refs_entity_has_permission(p.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REJECT') AND refs_entity_has_permission(p.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.REJECT') AND refs_entity_has_permission(p.source_entity_id,'GL.JE.REJECT') AND refs_entity_has_permission(p.target_entity_id,'GL.JE.REJECT') AND actor IS DISTINCT FROM source_created AND actor IS DISTINCT FROM target_created,'can_cancel',p.status='DRAFT_PAIR' AND source_status='DRAFT' AND target_status='DRAFT' AND refs_entity_has_permission(p.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.CANCEL') AND refs_entity_has_permission(p.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.CANCEL') AND actor IS DISTINCT FROM source_created AND actor IS DISTINCT FROM target_created,'can_post',p.status='APPROVED_PAIR' AND refs_entity_has_permission(p.source_entity_id,'REAL_ESTATE.UNIT_TRANSFER.POST') AND refs_entity_has_permission(p.target_entity_id,'REAL_ESTATE.UNIT_TRANSFER.POST') AND refs_entity_has_permission(p.source_entity_id,'GL.JE.POST') AND refs_entity_has_permission(p.target_entity_id,'GL.JE.POST') AND actor IS DISTINCT FROM source_created AND actor IS DISTINCT FROM source_reviewed AND actor IS DISTINCT FROM source_approved AND actor IS DISTINCT FROM target_created AND actor IS DISTINCT FROM target_reviewed AND actor IS DISTINCT FROM target_approved));
END;$$;
CREATE FUNCTION refs_read_unit_transfer_register(p_tenant uuid,p_entity uuid,p_period uuid,p_limit integer,p_after_date date,p_after_pair uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE rows jsonb;more boolean;next_cursor jsonb;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 OR num_nonnulls(p_after_date,p_after_pair) NOT IN(0,2) THEN RAISE EXCEPTION 'Invalid Unit Transfer register cursor' USING ERRCODE='22023';END IF;
 PERFORM refs_assert_scope(p_tenant,p_entity,'REAL_ESTATE.UNIT_TRANSFER.VIEW');PERFORM refs_assert_scope(p_tenant,p_entity,'GL.JE.VIEW');PERFORM 1 FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND ledger_code='PRIMARY';IF NOT FOUND THEN RAISE EXCEPTION 'Unit Transfer period is outside the company' USING ERRCODE='22023';END IF;
 WITH candidates AS MATERIALIZED(
  SELECT p.transfer_date,p.unit_transfer_pair_id FROM unit_transfer_pair p
  WHERE p.tenant_id=p_tenant AND(p.source_entity_id=p_entity AND p.source_period_id=p_period OR p.target_entity_id=p_entity AND p.target_period_id=p_period)
   AND(p_after_date IS NULL OR(p.transfer_date,p.unit_transfer_pair_id)<(p_after_date,p_after_pair))
  ORDER BY p.transfer_date DESC,p.unit_transfer_pair_id DESC LIMIT p_limit+1
 ),page AS(
  SELECT c.transfer_date,c.unit_transfer_pair_id,row_number() OVER(ORDER BY c.transfer_date DESC,c.unit_transfer_pair_id DESC) rn,refs_read_unit_transfer_pair(p_tenant,p_entity,c.unit_transfer_pair_id) row FROM candidates c
 )
 SELECT coalesce(jsonb_agg(page.row ORDER BY page.transfer_date DESC,page.unit_transfer_pair_id DESC) FILTER(WHERE page.rn<=p_limit),'[]'::jsonb),count(*)>p_limit,
  CASE WHEN count(*)>p_limit THEN(SELECT jsonb_build_object('transfer_date',tail.transfer_date,'unit_transfer_pair_id',tail.unit_transfer_pair_id) FROM page tail WHERE tail.rn=p_limit) ELSE NULL END
 INTO rows,more,next_cursor FROM page;
 RETURN jsonb_build_object('schema_version','UNIT_TRANSFER_REGISTER_V1','entity_id',p_entity,'period_id',p_period,'read_at',statement_timestamp(),'rows',rows,'limit',p_limit,'has_more',more,'next_cursor',next_cursor,'action_flags',jsonb_build_object('can_create_draft',false,'can_submit',false,'can_review',false,'can_approve',false,'can_reject',false,'can_cancel',false,'can_post',false));
END;$$;

